function _gtRichPlainText(html){return _gtParseRichRuns(html).map(function(r){return r.text;}).join('');}

function _gtParseRichRuns(html){
  const box=document.createElement('div');box.innerHTML=String(html||'');
  const runs=[];
  function walk(node,bold,italic,underline){
    node.childNodes.forEach(function(n){
      if(n.nodeType===3){
        if(n.nodeValue)runs.push({text:n.nodeValue,bold:bold,italic:italic,underline:underline});
      }else if(n.nodeType===1){
        const tag=n.tagName;
        if(tag==='BR'){runs.push({text:' ',bold:bold,italic:italic,underline:underline});return;}
        const mark=_GT_RICH_TAGS[tag];
        walk(n,bold||mark==='bold',italic||mark==='italic',underline||mark==='underline');
      }
    });
  }
  walk(box,false,false,false);
  return runs;
}

