  const out=runs.map(function(r){return {text:r.text,bold:r.bold,italic:r.italic,underline:r.underline};});
  while(out.length){
    const last=out[out.length-1];
    if(last.text.length<=1){out.pop();continue;}
    last.text=last.text.slice(0,-1);
    const withEllipsis=out.concat([{text:'…',bold:last.bold,italic:last.italic,underline:false}]);
    if(_gtMeasureRichRuns(ctx,withEllipsis,weightBase,sizePx,family)<=maxW)return withEllipsis;
