function _gtDrawRichRuns(ctx,runs,x,y,weightBase,sizePx,family,align,color){
  align=align||'left';
  const widths=runs.map(function(r){ctx.font=_gtRichFontStr(weightBase,r,sizePx,family);return ctx.measureText(r.text).width;});
