function _gtDrawGmcWeather(ctx,W,H,st){
  let sc=(parseFloat(st.scalePct)||100)/100;if(!isFinite(sc)||sc<=0)sc=1;
  const FF='"Roboto","Helvetica Neue",Arial,sans-serif';
