  ctx.save();ctx.fillStyle=PANEL;ctx.fillRect(mx,my,mw,mh);ctx.restore();
  const edge=Math.round(W*0.014); // inner text padding from the panel edges
  const lm=Math.max(6,Math.round(W*0.010)); // small left margin for the map
  const lat=parseFloat(st.lat),lng=parseFloat(st.lng);
