  // square, capped so it never eats too much width on narrow (portrait) images
  const gap=Math.max(3,Math.round(mh*0.035));
  const mapSide=Math.min(mh-gap*2,Math.round(mw*0.24));
  const mapH=mapSide,mapW=st.showMap?mapSide:0,mapX=mx+lm,mapY=my+Math.round((mh-mapSide)/2);
  if(st.showMap){
    const mapR=Math.round(mapH*0.16);
    ctx.save();ctx.shadowColor='rgba(0,0,0,0.5)';ctx.shadowBlur=Math.round(mh*0.05);ctx.shadowOffsetY=Math.round(mh*0.015);
    _gtRR(ctx,mapX,mapY,mapW,mapH,mapR);ctx.fillStyle='#111';ctx.fill();ctx.restore();
    ctx.save();_gtRR(ctx,mapX,mapY,mapW,mapH,mapR);ctx.clip();
    _gtDrawMiniMap(ctx,mapX,mapY,mapW,mapH,st.lat,st.lng);
    if(st.showCoord){const strH=Math.round(mapH*0.27);ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(mapX,mapY+mapH-strH,mapW,strH);}
    ctx.restore();
    if(st.showCoord){
      const cf=Math.max(10,Math.round(mapH*0.10));ctx.font=cf+'px '+FF;ctx.fillStyle='#fff';ctx.textAlign='left';
      ctx.fillText('Lat '+(isFinite(lat)?lat.toFixed(6):'-')+'°',mapX+Math.round(mapH*0.05),mapY+mapH-Math.round(mapH*0.155));
      ctx.fillText('Long '+(isFinite(lng)?lng.toFixed(6):'-')+'°',mapX+Math.round(mapH*0.05),mapY+mapH-Math.round(mapH*0.05));
    }
  }
