  const ix=mapX+(st.showMap?mapW:0)+Math.round(W*0.013);
  const rightCol=Math.round(mw*0.14);
  const iw=Math.max(60,mx+mw-edge-rightCol-ix);
  const fDate=Math.max(15,Math.round(mh*0.15)),fTime=Math.max(11,Math.round(mh*0.10));
  const fLoc=Math.max(16,Math.round(mh*0.17)),fAddr=Math.max(11,Math.round(mh*0.10));
  const d=_gtDateObj(st);let hr=d.getHours();const ampm=hr>=12?'PM':'AM';hr=hr%12;if(hr===0)hr=12;
  let topY=my+Math.round(mh*0.21);
  let timeY=topY+Math.round(fTime*1.45); // baseline of the day/time subline
  if(st.showDt){
    const dstr=d.getDate()+' '+_GT_MON_EN[d.getMonth()]+', '+d.getFullYear();
    const tstr=_GT_DAY_EN[d.getDay()]+', '+hr+':'+_gtP2s(d.getMinutes())+' '+ampm;
    ctx.textAlign='left';
    ctx.font='500 '+fDate+'px '+FF;ctx.fillStyle='#fff';ctx.fillText(dstr,ix,topY);
    ctx.font=fTime+'px '+FF;ctx.fillStyle='#d6dde2';ctx.fillText(tstr,ix,timeY);
