function _gtDownloadTemplateWithDropdowns(XL,wb,header){
  const FALLBACK=function(){XL.writeFile(wb,'Template_Geotag_Batch.xlsx');};
  try{
    if(typeof fflate==='undefined'){FALLBACK();return;}
    const colLetter=function(name){const i=header.indexOf(name);return i<0?null:XL.utils.encode_col(i);};
