function _gtApplyRemix(st,p){
  p=p||st;
  if(!p||!p.remix)return st;
  const out=Object.assign({},st);
  const lat=parseFloat(st.lat),lng=parseFloat(st.lng);
  if(isFinite(lat)&&isFinite(lng)){const j=_gtJitterCoord(lat,lng,p.remixRadius);out.lat=j.lat.toFixed(7);out.lng=j.lng.toFixed(7);}
  const base=st.dt?new Date(st.dt):new Date();
  const secs=(p.remixSeconds!=null?p.remixSeconds:(p.remixMinutes!=null?p.remixMinutes*60:60));
  const off=(Math.random()*2-1)*secs*1000;
  out.dt=_gtDtSec(new Date(base.getTime()+off));
  return out;
}

async function _gtFetchMapCanvas(lat,lng,style){
  if(!isFinite(lat)||!isFinite(lng)||!navigator.onLine)return null;
  try{
    const z=16,n=Math.pow(2,z);
    const xf=(lng+180)/360*n;
    const yf=(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*n;
    const xt=Math.floor(xf),yt=Math.floor(yf);
    const cv=document.createElement('canvas');cv.width=768;cv.height=768;
    const g=cv.getContext('2d');
    const jobs=[];
    for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){jobs.push(_gtLoadTile(z,xt+dx,yt+dy,style).then(function(im){g.drawImage(im,(dx+1)*256,(dy+1)*256);}));}
    await Promise.all(jobs);
    const cx=256+(xf-xt)*256,cy=256+(yf-yt)*256,size=480;
    const out=document.createElement('canvas');out.width=size;out.height=size;
    out.getContext('2d').drawImage(cv,cx-size/2,cy-size/2,size,size,0,0,size,size);
    return out;
  }catch(e){return null;}
}

function _gtLoadTile(z,x,y,style){
  return new Promise(function(res,rej){
    const im=new Image();
    im.crossOrigin='anonymous';
    im.onload=function(){res(im);};
    im.onerror=rej;
    im.src=_gtTileUrl(style||'street',z,x,y);
    // Esri satellite/topo tiles are noticeably slower than OSM; a tight 6 s
    // budget made the satellite map silently fall back to the schematic on
    // slower connections. 15 s is still bounded but lets satellite load.
    setTimeout(function(){rej(new Error('timeout'));},15000);
  });
}

function _gtTileUrl(style,z,x,y){
  if(style==='satellite')return 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/'+z+'/'+y+'/'+x;
  if(style==='terrain')return 'https://a.tile.opentopomap.org/'+z+'/'+x+'/'+y+'.png';
  if(style==='hybrid')return 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/'+z+'/'+y+'/'+x;
  return 'https://tile.openstreetmap.org/'+z+'/'+x+'/'+y+'.png';
}

