function _gtExcelDate(v){
  if(v instanceof Date&&!isNaN(v))return _gtFmtDt(v);
  if(typeof v==='number'&&isFinite(v)){const d=new Date(Math.round((v-25569)*86400*1000));if(!isNaN(d))return _gtFmtDt(d);}
  if(typeof v==='string'&&v.trim()){const d=new Date(v.trim());if(!isNaN(d))return _gtFmtDt(d);return v.trim();}
  return '';
}

function _gtFmtDt(d){return d.getFullYear()+'-'+_gtP2(d.getMonth()+1)+'-'+_gtP2(d.getDate())+'T'+_gtP2(d.getHours())+':'+_gtP2(d.getMinutes());}

function _gtP2(n){return String(n).padStart(2,'0');}

function _gtBool(v,def){
  if(v===''||v===undefined||v===null)return def;
  const s=String(v).toLowerCase().trim();
  if(['ya','yes','true','1','y','ada','tampil'].indexOf(s)>=0)return true;
  if(['tidak','no','false','0','n','tanpa','sembunyi'].indexOf(s)>=0)return false;
  return def;
}

function _imCoords(lat,lng){return lat!=null&&lng!=null&&String(lat).trim()!==''&&String(lng).trim()!==''&&Number.isFinite(Number(lat))&&Number.isFinite(Number(lng))&&Math.abs(Number(lat))<=90&&Math.abs(Number(lng))<=180;}

function _gtMatchPhoto(code,used){
