function _gtBatchDt(o){
  var t=_gtXlTgl(o.tanggal),j=_gtXlJam(o.jam);
  if(t)return t+' '+(j||'00:00');
  return o.tanggaljam||o.tanggal||o.datetime||o.waktu||'';
