function _gtXlJam(v){
  if(v instanceof Date&&!isNaN(v))return ('0'+v.getHours()).slice(-2)+':'+('0'+v.getMinutes()).slice(-2);
  if(typeof v==='number'&&isFinite(v)){var fr=v-Math.floor(v),mn=Math.round(fr*1440);return ('0'+Math.floor(mn/60)%24).slice(-2)+':'+('0'+mn%60).slice(-2);}
  return _gtCsvJam(v);
}

function _gtCsvJam(s){
  s=String(s==null?'':s).trim();if(!s)return '';
  var m=s.match(/^(\d{1,2})[:.](\d{2})(?:[:.]\d{2})?\s*(AM|PM)?$/i);if(!m)return '';
  var h=+m[1],mi=m[2];if(m[3]){var ap=m[3].toUpperCase();if(ap==='PM'&&h<12)h+=12;if(ap==='AM'&&h===12)h=0;}
  if(h>23||+mi>59)return '';
  return ('0'+h).slice(-2)+':'+mi;
}

function _gtXlTgl(v){
  if(v instanceof Date&&!isNaN(v))return v.getFullYear()+'-'+('0'+(v.getMonth()+1)).slice(-2)+'-'+('0'+v.getDate()).slice(-2);
  if(typeof v==='number'&&isFinite(v)){var d=new Date(Math.round((v-25569)*86400*1000));return d.getUTCFullYear()+'-'+('0'+(d.getUTCMonth()+1)).slice(-2)+'-'+('0'+d.getUTCDate()).slice(-2);}
  return _gtCsvTgl(v);
}

function _gtCsvTgl(s){
  s=String(s==null?'':s).trim();if(!s)return '';
  var m=s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);if(m)return m[1]+'-'+('0'+m[2]).slice(-2)+'-'+('0'+m[3]).slice(-2);
  m=s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/);if(m)return m[3]+'-'+('0'+m[2]).slice(-2)+'-'+('0'+m[1]).slice(-2);
  var d=new Date(s);if(!isNaN(d.getTime()))return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);
  return '';
}

