function _gtRenderList(){
  _gtRefreshPreview();
  const host=document.getElementById('gt-list');if(!host)return;
  const q=window._gtQueue;
  if(!q.length){host.innerHTML='<div style="text-align:center;color:#bbb;font-size:13px;padding:18px">Belum ada foto.</div>';return;}
  const token=++_gtRenderToken;
  host.innerHTML='<div style="display:flex;gap:12px;flex-wrap:wrap">'+q.map(function(it,i){
    const sig=_gtThumbSig(it);
    const cached=(it._thumbSig===sig)?it._thumbUrl:null;
    return _gtThumbCardHtml(it,i,cached);
  }).join('')+'</div>';
  let idx=0;
  function step(){
    if(token!==_gtRenderToken)return;
    const start=(typeof performance!=='undefined'?performance.now():Date.now());
    while(idx<q.length&&((typeof performance!=='undefined'?performance.now():Date.now())-start)<28){
      const it=q[idx];
      const sig=_gtThumbSig(it);
      if(it._thumbSig!==sig){
        const cv=_gtItemStamp(it);
        const th=document.createElement('canvas');
        const sc=Math.min(1,260/cv.width);
        th.width=Math.round(cv.width*sc);th.height=Math.round(cv.height*sc);
        th.getContext('2d').drawImage(cv,0,0,th.width,th.height);
        it._thumbUrl=th.toDataURL('image/jpeg',0.75);
        it._thumbSig=sig;
        if(token===_gtRenderToken){
          const wrap=host.querySelector('.gt-thumb-card[data-idx="'+idx+'"] .gt-thumb-imgwrap');
          if(wrap)wrap.innerHTML='<img src="'+it._thumbUrl+'" style="width:100%;height:100%;object-fit:contain;display:block">';
        }
      }
      idx++;
    }
    if(idx<q.length)requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

