function _ep(s){return(s==null?'':String(s)).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

function _gtOpenItemPreview(idx){
  const q=window._gtQueue;
  if(!q||!q.length)return;
  let i=((idx%q.length)+q.length)%q.length;
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:9999;display:flex;align-items:center;justify-content:center;overflow:auto;padding:24px;box-sizing:border-box';
  ov.onclick=function(e){if(e.target===ov)_close();};
  const img=document.createElement('img');
  img.style.cssText='max-width:90vw;max-height:80vh;box-shadow:0 12px 50px rgba(0,0,0,.5);border-radius:6px;background:#fff';
  const caption=document.createElement('div');
  caption.style.cssText='position:fixed;bottom:20px;left:0;right:0;text-align:center;color:#fff;font-size:13px;font-family:inherit;text-shadow:0 1px 3px rgba(0,0,0,.6);pointer-events:none';
  const btnBase='position:fixed;top:50%;transform:translateY(-50%);z-index:10000;border:none;background:rgba(255,255,255,.85);color:#333;border-radius:50%;width:44px;height:44px;font-size:24px;cursor:pointer;font-family:inherit;line-height:44px;padding:0';
  const prevBtn=document.createElement('button');prevBtn.textContent='‹';prevBtn.style.cssText=btnBase+';left:20px';
  const nextBtn=document.createElement('button');nextBtn.textContent='›';nextBtn.style.cssText=btnBase+';right:20px';
  const closeBtn=document.createElement('button');
  closeBtn.textContent='✕ Tutup';
  closeBtn.style.cssText='position:fixed;top:16px;right:20px;z-index:10000;border:none;background:#fff;color:#333;border-radius:7px;padding:7px 14px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;box-shadow:0 4px 16px rgba(0,0,0,.3)';
  function _close(){document.removeEventListener('keydown',keyHandler);ov.remove();}
  closeBtn.onclick=_close;
  function render(){
    const cur=window._gtQueue[i];if(!cur){_close();return;}
    const cv=_gtItemStamp(cur);
    img.src=cv.toDataURL('image/png');
    caption.textContent=(i+1)+' / '+window._gtQueue.length+' — '+cur.name;
  }
  prevBtn.onclick=function(e){e.stopPropagation();i=((i-1)%window._gtQueue.length+window._gtQueue.length)%window._gtQueue.length;render();};
  nextBtn.onclick=function(e){e.stopPropagation();i=(i+1)%window._gtQueue.length;render();};
  function keyHandler(e){
    if(e.key==='ArrowLeft')prevBtn.onclick(e);
    else if(e.key==='ArrowRight')nextBtn.onclick(e);
    else if(e.key==='Escape')_close();
  }
  document.addEventListener('keydown',keyHandler);
  render();
  ov.appendChild(img);ov.appendChild(caption);
  if(window._gtQueue.length>1){ov.appendChild(prevBtn);ov.appendChild(nextBtn);}
  ov.appendChild(closeBtn);
  document.body.appendChild(ov);
}

async function _gtRefreshPreview(){
  const el=document.getElementById('gt-preview-canvas');if(!el)return;
  try{
    const q=window._gtQueue;
    let out;
    const capEl=document.getElementById('gt-preview-caption');
    if(q&&q.length){
      out=_gtItemStamp(q[0],{noUpscale:true});
      if(capEl)capEl.textContent=''+q[0].name+(q.length>1?' (foto 1 dari '+q.length+')':'');
    }else{
      const img=await _gtPlaceholderPhoto();if(!img)return;
      // stable placeholder "item" so remix (if on) stays consistent across renders
      window._gtPreviewPlaceholderItem=window._gtPreviewPlaceholderItem||{};
      const rst=_gtItemRemixState(window._gtPreviewPlaceholderItem);
      out=rst?_gtStamp({img:img,st:rst},{noUpscale:true}):_gtStamp({img:img},{noUpscale:true});
      if(capEl)capEl.textContent='(contoh placeholder — belum ada foto diunggah)';
    }
    const sc=Math.min(480/out.width,270/out.height);
    const w=Math.max(1,Math.round(out.width*sc)),h=Math.max(1,Math.round(out.height*sc));
    el.width=w;el.height=h;
    const g=el.getContext('2d');g.clearRect(0,0,w,h);g.imageSmoothingQuality='high';g.drawImage(out,0,0,w,h);
  }catch(e){}
}

function _gtPlaceholderPhoto(){if(window._gtPhPromise)return window._gtPhPromise;
  window._gtPhPromise=new Promise(function(res){var c=document.createElement('canvas');c.width=640;c.height=400;var g=c.getContext('2d');
    var sky=g.createLinearGradient(0,0,0,240);sky.addColorStop(0,'#7fb2d9');sky.addColorStop(1,'#cfe4ef');g.fillStyle=sky;g.fillRect(0,0,640,240);
    var grd=g.createLinearGradient(0,240,0,400);grd.addColorStop(0,'#9cb877');grd.addColorStop(1,'#6f8f4e');g.fillStyle=grd;g.fillRect(0,240,640,160);
    g.fillStyle='rgba(120,150,90,0.5)';for(var i=0;i<40;i++){var x=Math.random()*640,y=250+Math.random()*140;g.fillRect(x,y,6+Math.random()*10,3+Math.random()*6);}
    g.fillStyle='rgba(255,255,255,0.5)';g.beginPath();g.arc(500,80,34,0,7);g.arc(540,80,40,0,7);g.arc(470,90,30,0,7);g.fill();
    var im=new Image();im.onload=function(){res(im);};im.onerror=function(){res(null);};im.src=c.toDataURL('image/jpeg',0.82);});
  return window._gtPhPromise;}

function _gtMaybeAutoGeocode(){
  const st=_gtState();
  if(!st.autoAddr)return;
  const la=parseFloat(st.lat),lo=parseFloat(st.lng);
  if(!isFinite(la)||!isFinite(lo))return;
  _gtGeocode(true);
}

async function _gtGeocode(silent){
  const st=_gtState();
  const lat=parseFloat(st.lat),lng=parseFloat(st.lng);
  if(!isFinite(lat)||!isFinite(lng)){if(!silent&&typeof toast==='function')toast('⚠ Isi koordinat dulu.');return;}
  try{
    const r=await fetch('https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat='+lat+'&lon='+lng+'&accept-language=id&zoom=18&addressdetails=1',{headers:{'Accept':'application/json'}});
    const j=await r.json();
    const a=j.address||{};
    const kota=a.city||a.town||a.county||a.village||a.municipality||'';
    const prov=a.state||'';
    st.title=[kota,prov,'Indonesia'].filter(Boolean).join(', ');
    st.addr=j.display_name||st.addr;
    // granular fields used by the alternate templates
    st.loc=a.village||a.hamlet||a.suburb||a.neighbourhood||a.town||a.city||st.loc||'';
    st.kec=a.city_district||a.municipality||a.subdistrict||a.district||st.kec||'';
    st.kab=a.county||a.city||a.regency||st.kab||'';
    st.prov=prov||st.prov||'';
    _etRenderGeotag(document.getElementById('et-sub-content'));
    if(!silent&&typeof toast==='function')toast('✓ Alamat terisi dari peta online.');
  }catch(e){
    if(!silent&&typeof toast==='function')toast('⚠ Gagal mengambil alamat — sedang offline? Isi manual saja.');
  }
}

