function _gtGeserTandai(){
  var cv=document.getElementById('gt-pts-preview-canvas'),bx=document.getElementById('gt-geser-box'),S=window._gtPts,bb=S._bbox;
  if(!cv||!bx)return;
  if(!bb){bx.style.display='none';return;}
  var G=_gtGeserDef();
  G.x=Math.max(-bb.x,Math.min(1-bb.w-bb.x,G.x));G.y=Math.max(-bb.y,Math.min(1-bb.h-bb.y,G.y));
  var W=cv.clientWidth,H=cv.clientHeight;
  bx.style.display='block';bx.style.left=(cv.offsetLeft+(bb.x+G.x)*W)+'px';bx.style.top=(cv.offsetTop+(bb.y+G.y)*H)+'px';
  bx.style.width=(bb.w*W)+'px';bx.style.height=(bb.h*H)+'px';
