function _gtGeserDef(){var S=window._gtPts;S.geser=S.geser||{x:0,y:0};return S.geser;}

function _gtGeserOut(out,pratinjau){
  var S=window._gtPts,G=_gtGeserDef();
  if(pratinjau)S._bbox=_gtGeserBBox(out);
  if(!G.x&&!G.y)return out;
  var c=document.createElement('canvas');c.width=out.width;c.height=out.height;
  c.getContext('2d').drawImage(out,Math.round(G.x*out.width),Math.round(G.y*out.height));
  return c;
}

function _gtGeserBBox(cv){
  try{
    var w=Math.min(240,cv.width),h=Math.max(1,Math.round(cv.height*w/cv.width));
    var t=document.createElement('canvas');t.width=w;t.height=h;var g=t.getContext('2d');g.drawImage(cv,0,0,w,h);
    var d=g.getImageData(0,0,w,h).data,x0=w,y0=h,x1=-1,y1=-1;
    for(var y=0;y<h;y++)for(var x=0;x<w;x++){if(d[(y*w+x)*4+3]>8){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}}
    if(x1<0)return null;
    return {x:x0/w,y:y0/h,w:(x1-x0+1)/w,h:(y1-y0+1)/h};
  }catch(e){return null;}
}

function _gtCsvApply(st,pt){
  if(!pt||!st)return st;
  var S=window._gtPts||{};
  if(pt.dt)st.dt=pt.dt;
  if(S.csvProj)st.title=S.csvProj;
  var ext=[];
  if(pt.alt!==undefined&&pt.alt!==''&&isFinite(pt.alt))ext.push('Elv '+pt.alt+' m');
  if(pt.temp!==undefined&&pt.temp!==''&&isFinite(pt.temp))ext.push(pt.temp+'\u00b0C');
  if(pt.wind!==undefined&&pt.wind!==''&&isFinite(pt.wind))ext.push('Angin '+pt.wind+' km/j');
  var dasar=(pt.note!=null&&pt.note!=='')?pt.note:st.note;
  if(ext.length)st.note=(dasar?dasar+' \u00b7 ':'')+ext.join(' \u00b7 ');
  else if(pt.note!=null&&pt.note!=='')st.note=pt.note;
  if(pt.temp!==undefined&&pt.temp!==''&&isFinite(pt.temp))st.weather=pt.temp+'\u00b0C';
  if(pt.deg!==undefined&&pt.deg!==''&&isFinite(pt.deg)){st.showCone=true;st.coneDeg=pt.deg;}
  return st;
}

