  const out=[];
  const acts=(typeof ACTS!=='undefined'&&Array.isArray(ACTS))?ACTS:[];
  acts.forEach(function(a){
    if(site!=='all'&&a.site!==site)return;
    if(jenis!=='all'&&a.type!==jenis)return;
