function _gtActPts(a){
  if(typeof _coordParse!=='function')return [];
  const datum=a.coordDatum||'wgs84';
  const isTrench=a.type==='Trenching';
  const brg=(a.coordBearing!=null&&isFinite(a.coordBearing))?a.coordBearing:0;
  let main=null,start=null,end=null;
  if(isTrench){
    start=(a.coordStart&&a.coordStart.lat!=null)?{lat:a.coordStart.lat,lng:a.coordStart.lng}:(a.coordStart?_coordParse(a.coordStart.coord,datum):null);
    end=(a.coordEnd&&a.coordEnd.lat!=null)?{lat:a.coordEnd.lat,lng:a.coordEnd.lng}:(a.coordEnd?_coordParse(a.coordEnd.coord,datum):null);
    main=(start&&end)?{lat:(start.lat+end.lat)/2,lng:(start.lng+end.lng)/2}:(start||end||null);
  }else{main=_coordParse(a.coordMain,datum);}
  const off=(typeof _coordOffset==='function')?_coordOffset:null;
  const upBrg=(a.coordUpBearing!=null&&isFinite(a.coordUpBearing))?a.coordUpBearing:(brg+180)%360;
  const downBrg=(a.coordDownBearing!=null&&isFinite(a.coordDownBearing))?a.coordDownBearing:brg;
  const _adaRadius=!['Drilling','CSD','Airlift','Flushing'].includes(a.type);   // Y492
  const up=main&&off&&_adaRadius?off(main.lat,main.lng,500,upBrg):null;
  const down=main&&off&&_adaRadius?off(main.lat,main.lng,500,downBrg):null;
  const _b35=(a.farBearing!=null&&isFinite(a.farBearing))?a.farBearing:downBrg;
  const far35=isTrench&&main&&off&&_adaRadius?off(main.lat,main.lng,3500,_b35):null;   // Y493
  const tps=Array.isArray(a.coordTP)?a.coordTP:[];
  const pts=[];
  if(isTrench){
    if(start)pts.push({lat:start.lat,lng:start.lng,label:(a.coordStart.label||'Start')});
    if(end)pts.push({lat:end.lat,lng:end.lng,label:(a.coordEnd.label||'End')});
    if(main&&start&&end)pts.push({lat:main.lat,lng:main.lng,label:'Titik Tengah'});
  }else if(main)pts.push({lat:main.lat,lng:main.lng,label:'Utama'});
  if(up)pts.push({lat:up.lat,lng:up.lng,label:'Up 500m'});
  if(down)pts.push({lat:down.lat,lng:down.lng,label:'Down 500m'});
  if(far35)pts.push({lat:far35.lat,lng:far35.lng,label:'3500m'});   // Y493
  tps.forEach(function(t,i){const pp=(t.lat!=null&&t.lng!=null)?{lat:t.lat,lng:t.lng}:_coordParse(t.coord,datum);if(pp)pts.push({lat:pp.lat,lng:pp.lng,label:t.label||('TP'+(i+1))});});
  return pts;
}

function _coordParse(s,datum){
  if(s==null||String(s).trim()==='')return null;
  // Accept both raw field input (566820.22,9920029.53) and the display
  // format used by the guide (566,820.220E, 9,920,029.530N). A comma is a
  // thousands separator only when exactly three digits follow it; the comma
  // between two coordinates is followed by six or more digits and remains.
  var raw=String(s).trim().replace(/,(?=\d{3}(?:\D|$))/g,'');
  // Y402: buang kurung ( ) [ ] { } dan terima '/' sebagai pemisah -- di file
  // Program koordinat kadang ditulis "(566820.22 / 9920029.53)".
  var m=raw.replace(/[()\[\]{}]/g,' ').replace(/[EeNn]/g,' ').split(/[,;\/\s]+/).map(function(x){return parseFloat(x);}).filter(function(x){return isFinite(x);});
  if(m.length<2)return null;
  if(datum==='p2exc'){
    if(typeof _p2excToUtm!=='function')return null;
    var conv=_p2excToUtm(m[0],m[1]);
    var llp=_utmToLatLng(conv.e,conv.n,UTM_DEFAULT_ZONE,UTM_DEFAULT_HEMI);
    return {lat:llp.lat,lng:llp.lng};
  }
  if(Math.abs(m[0])<=90&&Math.abs(m[1])<=180)return {lat:m[0],lng:m[1]};
  if(m[0]>100000&&m[0]<999999&&m[1]>1000000){
    var ll=_utmToLatLng(m[0],m[1],UTM_DEFAULT_ZONE,UTM_DEFAULT_HEMI);
    return {lat:ll.lat,lng:ll.lng};
  }
  return null;
}

function _utmToLatLng(easting,northing,zone,hemi){
  var a=6378137.0,eccSquared=0.00669438,k0=0.9996;
  var e1=(1-Math.sqrt(1-eccSquared))/(1+Math.sqrt(1-eccSquared));
  var x=easting-500000.0,y=northing;
  if(hemi==='S'||hemi==='s')y-=10000000.0;
  var LongOrigin=(zone-1)*6-180+3;
  var eccPrimeSquared=eccSquared/(1-eccSquared);
  var M=y/k0;
  var mu=M/(a*(1-eccSquared/4-3*eccSquared*eccSquared/64-5*eccSquared*eccSquared*eccSquared/256));
  var phi1=mu+(3*e1/2-27*e1*e1*e1/32)*Math.sin(2*mu)
    +(21*e1*e1/16-55*e1*e1*e1*e1/32)*Math.sin(4*mu)
    +(151*e1*e1*e1/96)*Math.sin(6*mu);
  var N1=a/Math.sqrt(1-eccSquared*Math.sin(phi1)*Math.sin(phi1));
  var T1=Math.tan(phi1)*Math.tan(phi1);
  var C1=eccPrimeSquared*Math.cos(phi1)*Math.cos(phi1);
  var R1=a*(1-eccSquared)/Math.pow(1-eccSquared*Math.sin(phi1)*Math.sin(phi1),1.5);
  var D=x/(N1*k0);
  var lat=phi1-(N1*Math.tan(phi1)/R1)*(D*D/2-(5+3*T1+10*C1-4*C1*C1-9*eccPrimeSquared)*D*D*D*D/24
    +(61+90*T1+298*C1+45*T1*T1-252*eccPrimeSquared-3*C1*C1)*D*D*D*D*D*D/720);
  lat=lat*180/Math.PI;
  var lng=(D-(1+2*T1+C1)*D*D*D/6+(5-2*C1+28*T1-3*C1*C1+8*eccPrimeSquared+24*T1*T1)*D*D*D*D*D/120)/Math.cos(phi1);
  lng=LongOrigin+lng*180/Math.PI;
  return {lat:lat,lng:lng};
}

function _p2excToUtm(e,n){return {e:e*P2EXC_E_SCALE+P2EXC_E_OFFSET, n:n*P2EXC_N_SCALE+P2EXC_N_OFFSET};}

function _gtCsvPts(){
  var out=[];
  _gtCsvRows().forEach(function(r,i){
    if(!_gtCsvOk(r))return;
    out.push({name:r.name||('titik'+(i+1)),site:'',lat:r.lat,lng:r.lng,title:r.title,addr:r.addr,
      dt:r.date?(r.date+'T'+(r.time||'00:00')):'',note:r.note,deg:r.deg,alt:r.alt,temp:r.temp,wind:r.wind,_i:i});
  });
  return out;
}

function _gtCsvOk(r){return r&&r.lat!==''&&r.lng!==''&&isFinite(r.lat)&&isFinite(r.lng)&&Math.abs(r.lat)<=90&&Math.abs(r.lng)<=180;}

