function _gtEnsureMap(){
  const div=document.getElementById('gt-map');if(!div)return;
  if(window._gtMapInst){setTimeout(function(){try{window._gtMapInst.invalidateSize();}catch(e){}},50);return;}
  // Leaflet itself is bundled offline but only actually injected into the
  // page the first time any map feature needs it (same lazy loader the
  // Coordinate Transform tool and ENV Mon Program map already use) — reuse
  // it here instead of assuming `L` is already global.
  if(typeof window.L==='undefined'){
    if(typeof _coordEnsureLeaflet==='function'){
      _coordEnsureLeaflet().then(function(){_gtBuildMap(div);}).catch(function(e){console.warn('Geotag: Leaflet load failed',e);});
    }
