  // Expanded avoids the collapsed hamburger icon, whose image 404s offline
  // and shows as an empty white box. Boundary layers become toggleable here
  // instead of always-on, so nothing collides with a separate menu.
  const _baseLayers={'OpenStreetMap':osm,'Satelit (Esri)':sat,'Topografi':topo};
  const _overlays={};
