    ((typeof SAMPLING_POINTS!=='undefined'&&SAMPLING_POINTS[k])||[]).forEach(function(p){
      if(p.lat_d==null||p.lng_d==null)return;
      const nm=(p.sampleName||p.position||'').trim();if(!nm)return;
      const mk=L.circleMarker([p.lat_d,p.lng_d],{radius:5,color:'#1565c0',weight:1.5,fillColor:'#4285f4',fillOpacity:.85}).addTo(map);
      mk.bindTooltip(nm,{direction:'top'});
      mk.on('click',function(ev){L.DomEvent.stopPropagation(ev);_gtPickTitik(nm);});
    });
  });
  const st=_gtState();
