function _gtPickTitik(name){
  const st=_gtState();
  if(!name)return;
  let found=null;
  ['monthly','semesterly','yearly'].forEach(function(k){
    ((typeof SAMPLING_POINTS!=='undefined'&&SAMPLING_POINTS[k])||[]).forEach(function(m){
      if((m.sampleName||'').trim()===name&&m.lat_d!=null)found=m;
    });
  });
  if(found){
    st.lat=String(found.lat_d);st.lng=String(found.lng_d);
    st.title=(found.site||'')+', Kalimantan Timur, Indonesia';
    st.addr=name+', '+(found.site||'')+', Wilayah Kerja Mahakam, Kalimantan Timur, Indonesia';
    _gtPrepareMap();
    _etRenderGeotag(document.getElementById('et-sub-content'));
    _gtMaybeAutoGeocode();
  } else if(typeof toast==='function')toast('⚠ Titik itu belum punya koordinat di ENV Mon Program.');
}

async function _gtPrepareMap(){
  const st=_gtState();
  const lat=parseFloat(st.lat),lng=parseFloat(st.lng);
  st._mapCanvas=null;st._mapKey='';
  if(!isFinite(lat)||!isFinite(lng))return;
  const key=lat.toFixed(5)+','+lng.toFixed(5);
  if(!navigator.onLine)return;
  try{
    const z=16,n=Math.pow(2,z);
    const xf=(lng+180)/360*n;
    const yf=(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*n;
    const xt=Math.floor(xf),yt=Math.floor(yf);
    const cv=document.createElement('canvas');cv.width=768;cv.height=768;
    const g=cv.getContext('2d');
    const jobs=[];
    for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
      jobs.push(_gtLoadTile(z,xt+dx,yt+dy,st.mapStyle).then(function(im){g.drawImage(im,(dx+1)*256,(dy+1)*256);}));
    }
    await Promise.all(jobs);
    // center crop so the coordinate sits exactly in the middle — cropped
    // at a larger native resolution than before so it stays sharp even
    // when the stamped banner is scaled up on an upsized/HD photo
    const cx=256+(xf-xt)*256,cy=256+(yf-yt)*256;
    const size=480;
    const out=document.createElement('canvas');out.width=size;out.height=size;
    out.getContext('2d').drawImage(cv,cx-size/2,cy-size/2,size,size,0,0,size,size);
    st._mapCanvas=out;st._mapKey=key;
    _gtRenderList();
  }catch(e){st._mapCanvas=null;}
}

