      it.cloneSource={x:p.x,y:p.y};it.cloneOffset=null;
      _gtCleanRenderBase();
      _gtCleanSetMode('clonepaint');
      return;
    }
    if(C.mode==='clonepaint'){
      if(!it.cloneSource){if(typeof toast==='function')toast('⚠ Pilih dulu Titik Sumber Klon sebelum melukis.');return;}
      it._drawing=true;lastPaintPos=p;paintedAny=true;
      _gtCleanCloneDabAt(it,p.x,p.y);
