function _gtCleanRenderBase(){
  const it=_gtCleanActive();const cv=document.getElementById('gtclean-canvas');if(!cv)return;
  const undoBtn=document.getElementById('gtclean-undo'),redoBtn=document.getElementById('gtclean-redo');
