    if(undoBtn)undoBtn.disabled=true;
    if(redoBtn)redoBtn.disabled=true;
    return;
  }
  const maxW=560;
  const sc=Math.min(1,maxW/it.img.naturalWidth);
  window._gtClean.scale=sc;
  cv.width=Math.round(it.img.naturalWidth*sc);cv.height=Math.round(it.img.naturalHeight*sc);
  const g=cv.getContext('2d');
  g.drawImage(it.resultCanvas||it.img,0,0,cv.width,cv.height);
  if(it.mask)_gtCleanDrawRectOutline(g,it.mask,sc,'#e53935');
  if(it.src)_gtCleanDrawRectOutline(g,it.src,sc,'#2e7d32');
  if(it.cloneSource){
