    g.beginPath();g.arc(it.cloneSource.x*sc,it.cloneSource.y*sc,7,0,Math.PI*2);g.stroke();
    g.beginPath();g.moveTo(it.cloneSource.x*sc-10,it.cloneSource.y*sc);g.lineTo(it.cloneSource.x*sc+10,it.cloneSource.y*sc);
    g.moveTo(it.cloneSource.x*sc,it.cloneSource.y*sc-10);g.lineTo(it.cloneSource.x*sc,it.cloneSource.y*sc+10);g.stroke();
  }
