function _gtCleanActive(){
  const C=window._gtClean;
  return C.queue.find(function(q){return q.id===C.activeId;})||null;
}

function _gtCleanRenderList(){
  const host=document.getElementById('gtclean-list');if(!host)return;
  const C=window._gtClean;
  if(!C.queue.length){host.innerHTML='<div style="text-align:center;color:#bbb;font-size:13px;padding:10px">Belum ada foto diantrikan.</div>';return;}
  host.innerHTML='<div style="display:flex;gap:8px;flex-wrap:wrap">'+C.queue.map(function(it){
    const active=it.id===C.activeId;
    const done=it.historyIdx>0;
    return '<div style="width:72px" title="'+_ep(it.name)+'">'
     +'<div style="position:relative;width:72px;height:72px">'
     +'<div onclick="_gtCleanSelect('+it.id+')" style="cursor:pointer;border:2px solid '+(active?'#1565c0':'var(--g2)')+';border-radius:7px;overflow:hidden;width:72px;height:72px;background:repeating-conic-gradient(#e8e8e8 0% 25%,#fff 0% 50%) 50%/10px 10px">'
     +'<img src="'+it.img.src+'" style="width:100%;height:100%;object-fit:cover;display:block">'
     +'</div>'
     +(done?'<span style="position:absolute;bottom:2px;left:2px;background:#2e7d32;color:#fff;border-radius:4px;font-size:11px;padding:1px 4px;font-weight:700">✓</span>':'')
     +'<button onclick="event.stopPropagation();_gtCleanRemoveItem('+it.id+')" title="Hapus foto ini dari antrian" style="position:absolute;top:-6px;right:-6px;width:19px;height:19px;border-radius:50%;border:none;background:#c62828;color:#fff;font-size:13px;line-height:19px;padding:0;cursor:pointer;font-weight:700">✕</button>'
     +'</div>'
     +'<div style="font-size:11px;color:var(--g3);text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px">'+_ep(it.name)+'</div>'
     +'</div>';
  }).join('')+'</div>';
}

function _gtCleanRemoveItem(id){
  const C=window._gtClean;
  const idx=C.queue.findIndex(function(q){return q.id===id;});
  if(idx<0)return;
  const it=C.queue[idx];
  if(it.url)try{URL.revokeObjectURL(it.url);}catch(e){}
  C.queue.splice(idx,1);
  if(C.activeId===id){
    C.activeId=C.queue.length?C.queue[Math.min(idx,C.queue.length-1)].id:null;
  }
  _gtCleanRenderList();
  _gtCleanRenderBase();
}

function _gtCleanSelect(id){
  window._gtClean.activeId=id;
  _gtCleanSetMode('mask');
  _gtCleanRenderList();
  _gtCleanRenderBase();
}

