  if(m==='clonesrc'){const it=_gtCleanActive();if(it)it.cloneOffset=null;} // picking a new source resets the aligned offset
  const ids={mask:'#c62828',src:'#2e7d32',clonesrc:'#5e35b1',clonepaint:'#5e35b1'};
  ['mask','src','clonesrc','clonepaint'].forEach(function(k){
    const el=document.getElementById('gtclean-mode-'+k);
    if(el)el.style.borderColor=(m===k)?ids[k]:'transparent';
  });
}

function _gtCleanCloneCanvas(cv){
  const c=document.createElement('canvas');c.width=cv.width;c.height=cv.height;
  c.getContext('2d').drawImage(cv,0,0);
  return c;
}

function _gtCleanPushHistory(it){
  const base=_gtCleanEnsureWorkingCanvas(it);
  const snap=_gtCleanCloneCanvas(base);
  it.history=(it.history||[]).slice(0,(it.historyIdx==null?-1:it.historyIdx)+1);
  it.history.push(snap);
  if(it.history.length>20)it.history.shift();
  it.historyIdx=it.history.length-1;
}

function _gtCleanEnsureWorkingCanvas(it){
  if(!it.resultCanvas){
    const cv=document.createElement('canvas');
    cv.width=it.img.naturalWidth;cv.height=it.img.naturalHeight;
    cv.getContext('2d').drawImage(it.img,0,0);
    it.resultCanvas=cv;
  }
  return it.resultCanvas;
}

function _gtCleanCloneDabAt(it,px,py){
  if(!it.cloneSource)return;
  if(!it.cloneOffset)it.cloneOffset={dx:it.cloneSource.x-px,dy:it.cloneSource.y-py};
  const cv=_gtCleanEnsureWorkingCanvas(it);
  const ctx=cv.getContext('2d');
  const r=Math.max(4,window._gtClean.brush||24);
  const sx=px+it.cloneOffset.dx,sy=py+it.cloneOffset.dy;
  if(sx-r<0||sy-r<0||sx+r>cv.width||sy+r>cv.height||px-r<0||py-r<0||px+r>cv.width||py+r>cv.height)return;
  const size=r*2;
  const patch=document.createElement('canvas');patch.width=size;patch.height=size;
  const pctx=patch.getContext('2d');
  pctx.drawImage(cv,sx-r,sy-r,size,size,0,0,size,size);
  const maskCv=document.createElement('canvas');maskCv.width=size;maskCv.height=size;
  const mctx=maskCv.getContext('2d');
  const grad=mctx.createRadialGradient(r,r,r*0.55,r,r,r);
  grad.addColorStop(0,'rgba(0,0,0,1)');grad.addColorStop(1,'rgba(0,0,0,0)');
  mctx.fillStyle=grad;mctx.fillRect(0,0,size,size);
  pctx.globalCompositeOperation='destination-in';
  pctx.drawImage(maskCv,0,0);
  pctx.globalCompositeOperation='source-over';
  ctx.drawImage(patch,px-r,py-r);
}

