async function _gtHandleFiles(files){
  for(const f of Array.from(files||[])){
    if(!/^image\//.test(f.type)&&!/\.(jpe?g|png|webp)$/i.test(f.name))continue;
    const url=URL.createObjectURL(f);
    let img=await new Promise(function(res,rej){const im=new Image();im.onload=function(){res(im);};im.onerror=rej;im.src=url;});
    if(window._gtAutoClean){
      try{
        const cv=document.createElement('canvas');cv.width=img.naturalWidth;cv.height=img.naturalHeight;
        const cx=cv.getContext('2d');cx.drawImage(img,0,0);
        const region=_gtDetectStampRegion(cv);
        if(region){
          _gtCleanHarmonicFill(cx,cv.width,cv.height,region.x,region.y,region.w,region.h);
          img=await new Promise(function(res){const im2=new Image();im2.onload=function(){res(im2);};im2.src=cv.toDataURL('image/png');});
          if(typeof toast==='function')toast('Stempel lama terdeteksi & dihapus otomatis di '+f.name);
        }
      }catch(e){}
    }
    window._gtQueue.push({name:f.name,img:img,url:url});
  }
  _gtRenderList();
}

function _gtCleanHarmonicFill(bg,W,H,mx,my,mw,mh){
  const pad=Math.max(20,Math.round(Math.max(mw,mh)*0.25));
  const rx=Math.max(0,Math.floor(mx-pad)),ry=Math.max(0,Math.floor(my-pad));
  const rw=Math.min(W,Math.ceil(mx+mw+pad))-rx,rh=Math.min(H,Math.ceil(my+mh+pad))-ry;
  const lmx=Math.round(mx-rx),lmy=Math.round(my-ry),lmw=Math.round(mw),lmh=Math.round(mh);
  const origData=bg.getImageData(rx,ry,rw,rh);
  const knownCanvas=document.createElement('canvas');knownCanvas.width=rw;knownCanvas.height=rh;
  const kctx=knownCanvas.getContext('2d');
  kctx.putImageData(origData,0,0);
  kctx.clearRect(lmx,lmy,lmw,lmh);
  const seedData=new ImageData(new Uint8ClampedArray(origData.data),rw,rh);
  let rSum=0,gSum=0,bSum=0,cnt=0;
  for(let xx=0;xx<rw;xx++){[0,rh-1].forEach(function(yy){const i=(yy*rw+xx)*4;rSum+=origData.data[i];gSum+=origData.data[i+1];bSum+=origData.data[i+2];cnt++;});}
  for(let yy=0;yy<rh;yy++){[0,rw-1].forEach(function(xx){const i=(yy*rw+xx)*4;rSum+=origData.data[i];gSum+=origData.data[i+1];bSum+=origData.data[i+2];cnt++;});}
  const avg=[rSum/(cnt||1),gSum/(cnt||1),bSum/(cnt||1)];
  for(let yy=lmy;yy<lmy+lmh;yy++)for(let xx=lmx;xx<lmx+lmw;xx++){
    const i=(yy*rw+xx)*4;
    seedData.data[i]=avg[0];seedData.data[i+1]=avg[1];seedData.data[i+2]=avg[2];seedData.data[i+3]=255;
  }
  let rc=document.createElement('canvas');rc.width=rw;rc.height=rh;
  rc.getContext('2d').putImageData(seedData,0,0);
  const PASSES=28;
  for(let p=0;p<PASSES;p++){
    const tmp=document.createElement('canvas');tmp.width=rw;tmp.height=rh;
    const tctx=tmp.getContext('2d');
    tctx.filter='blur('+(p<PASSES*0.6?5:2)+'px)';
    tctx.drawImage(rc,0,0);
    tctx.filter='none';
    tctx.drawImage(knownCanvas,0,0);
    rc=tmp;
  }
  bg.drawImage(rc,rx,ry);
}

function _gtDetectStampRegion(canvas){
  const W=canvas.width,H=canvas.height;
  const ctx=canvas.getContext('2d');
  const candidates=[
    {x:0,y:Math.round(H*0.78),w:W,h:Math.round(H*0.22)},
    {x:0,y:Math.round(H*0.62),w:Math.round(W*0.55),h:Math.round(H*0.38)},
    {x:Math.round(W*0.45),y:0,w:Math.round(W*0.55),h:Math.round(H*0.22)},
    {x:Math.round(W*0.45),y:Math.round(H*0.72),w:Math.round(W*0.55),h:Math.round(H*0.28)}
  ];
  let best=null,bestScore=-1;
  candidates.forEach(function(r){
    if(r.w<10||r.h<10)return;
    let data;
    try{data=ctx.getImageData(r.x,r.y,r.w,r.h).data;}catch(e){return;}
    let sum=0,sumSq=0;const n=data.length/4;
    for(let i=0;i<data.length;i+=4){
      const lum=data[i]*0.299+data[i+1]*0.587+data[i+2]*0.114;
      sum+=lum;sumSq+=lum*lum;
    }
    const mean=sum/n;
    const variance=sumSq/n-mean*mean;
    const score=(mean<95?1:0)*(variance<1800?(1800-variance)/1800:0);
    if(score>bestScore){bestScore=score;best=r;}
  });
  return (best&&bestScore>0.15)?best:null;
}

