function _gtCleanDownload(){
  const it=_gtCleanActive();
  if(!it){if(typeof toast==='function')toast('⚠ Belum ada foto aktif untuk diunduh.');return;}
  const cv=_gtCleanEnsureWorkingCanvas(it);
  const a=document.createElement('a');
  a.href=cv.toDataURL('image/jpeg',0.95);
  a.download='clean_'+_stdFileName(it.name)+'.jpg';
  document.body.appendChild(a);a.click();a.remove();
}

function _gtCleanProcess(kind){
  const it=_gtCleanActive();
  const status=document.getElementById('gtclean-status');
  if(!it){if(typeof toast==='function')toast('⚠ Belum ada foto aktif -- upload/pilih foto dulu.');return;}
  if(!it.mask||it.mask.w<4||it.mask.h<4){if(typeof toast==='function')toast('⚠ Tandai dulu area yang mau dihilangkan (kotak merah).');return;}
  if(kind==='patch'&&(!it.src||it.src.w<4||it.src.h<4)){if(typeof toast==='function')toast('⚠ Tandai dulu area sumber tekstur (kotak hijau) untuk mode Source Patch.');return;}
  const cv=_gtCleanEnsureWorkingCanvas(it);
  const bg=cv.getContext('2d');
  const mask=it.mask,src=it.src;
  if(status)status.textContent='Memproses...';
  setTimeout(function(){
    try{
      if(kind==='auto'){
        _gtCleanHarmonicFill(bg,cv.width,cv.height,mask.x,mask.y,mask.w,mask.h);
      }else if(kind==='autopatch'){
        const found=_gtCleanAutoFindSource(bg,mask.x,mask.y,mask.w,mask.h);
        if(!found){if(status)status.textContent='⚠ Tidak menemukan area sumber yang cocok di sekitar -- coba tandai manual (kotak hijau) lalu pakai Source Patch.';return;}
        _gtCleanPatchFill(bg,found,mask.x,mask.y,mask.w,mask.h);
      }else{
        _gtCleanPatchFill(bg,src,mask.x,mask.y,mask.w,mask.h);
      }
      it.mask=null;it.src=null;
      _gtCleanPushHistory(it);
      _gtCleanRenderList();
      _gtCleanRenderBase();
      if(status)status.textContent='✓ Selesai. Bisa ditandai & diproses lagi di area lain, atau langsung unduh.';
    }catch(e){if(status)status.textContent='⚠ Gagal memproses: '+(e.message||e);}
  },30);
}

function _gtCleanPatchFill(bg,srcRect,mx,my,mw,mh){
  mx=Math.round(mx);my=Math.round(my);mw=Math.round(mw);mh=Math.round(mh);
  const sx=Math.round(srcRect.x),sy=Math.round(srcRect.y),sw=Math.round(srcRect.w),sh=Math.round(srcRect.h);
  const patch=document.createElement('canvas');patch.width=mw;patch.height=mh;
  const pctx=patch.getContext('2d');
  for(let yy=0;yy<mh;yy+=sh){
    for(let xx=0;xx<mw;xx+=sw){
      pctx.drawImage(bg.canvas,sx,sy,sw,sh,xx,yy,Math.min(sw,mw-xx),Math.min(sh,mh-yy));
    }
  }
  const destMean=_gtCleanBorderMeanColor(bg,mx,my,mw,mh);
  const srcMean=_gtCleanMeanColor(bg,sx,sy,sw,sh);
  if(destMean&&srcMean){
    const dr=destMean.r-srcMean.r,dg=destMean.g-srcMean.g,db=destMean.b-srcMean.b;
    const pdata=pctx.getImageData(0,0,mw,mh);
    const d=pdata.data;
    for(let i=0;i<d.length;i+=4){
      d[i]=Math.max(0,Math.min(255,d[i]+dr));
      d[i+1]=Math.max(0,Math.min(255,d[i+1]+dg));
      d[i+2]=Math.max(0,Math.min(255,d[i+2]+db));
    }
    pctx.putImageData(pdata,0,0);
  }
  // 1) fully replace the masked area first, at full opacity -- guarantees
  // the old stamp is completely gone everywhere inside the rect (no
  // partial-opacity "ghosting" of the old content showing through)
  bg.drawImage(patch,mx,my);
  // 2) soften the seam with a wide smoothstep feather so the whole patch
  // blends into the surrounding photo, not just a thin ring at the edge
  const feather=Math.max(8,Math.round(Math.min(mw,mh)*0.18));
  const rx=Math.max(0,mx-feather),ry=Math.max(0,my-feather);
  const rw=Math.min(bg.canvas.width,mx+mw+feather)-rx,rh=Math.min(bg.canvas.height,my+mh+feather)-ry;
  const seam=bg.getImageData(rx,ry,rw,rh);
  const seamCv=document.createElement('canvas');seamCv.width=rw;seamCv.height=rh;
  seamCv.getContext('2d').putImageData(seam,0,0);
  const blurred=document.createElement('canvas');blurred.width=rw;blurred.height=rh;
  const bctx=blurred.getContext('2d');
  bctx.filter='blur('+feather+'px)';
  bctx.drawImage(seamCv,0,0);
  bctx.filter='none';
  const ringMask=document.createElement('canvas');ringMask.width=rw;ringMask.height=rh;
  const rmctx=ringMask.getContext('2d');
  rmctx.filter='blur('+Math.max(2,Math.round(feather*0.9))+'px)';
  rmctx.strokeStyle='#000';rmctx.lineWidth=feather*1.8;
  rmctx.strokeRect(mx-rx,my-ry,mw,mh);
  rmctx.filter='none';
  bctx.globalCompositeOperation='destination-in';
  bctx.drawImage(ringMask,0,0);
  bctx.globalCompositeOperation='source-over';
  bg.drawImage(blurred,rx,ry);
}

function _gtCleanMeanColor(ctx,x,y,w,h){
  x=Math.max(0,Math.round(x));y=Math.max(0,Math.round(y));
  w=Math.max(1,Math.round(w));h=Math.max(1,Math.round(h));
  w=Math.min(w,ctx.canvas.width-x);h=Math.min(h,ctx.canvas.height-y);
  if(w<=0||h<=0)return null;
  const data=ctx.getImageData(x,y,w,h).data;
  let r=0,g=0,b=0;const n=data.length/4;
  for(let i=0;i<data.length;i+=4){r+=data[i];g+=data[i+1];b+=data[i+2];}
  return {r:r/n,g:g/n,b:b/n};
}

function _gtCleanBorderMeanColor(bg,mx,my,mw,mh){
  const W=bg.canvas.width,H=bg.canvas.height;
  const band=Math.max(4,Math.round(Math.min(mw,mh)*0.12));
  const parts=[];
  if(my-band>=0)parts.push(_gtCleanMeanColor(bg,mx,my-band,mw,band));
  if(my+mh+band<=H)parts.push(_gtCleanMeanColor(bg,mx,my+mh,mw,band));
  if(mx-band>=0)parts.push(_gtCleanMeanColor(bg,mx-band,my,band,mh));
  if(mx+mw+band<=W)parts.push(_gtCleanMeanColor(bg,mx+mw,my,band,mh));
  const valid=parts.filter(Boolean);
  if(!valid.length)return null;
  return {
    r:valid.reduce(function(s,p){return s+p.r;},0)/valid.length,
    g:valid.reduce(function(s,p){return s+p.g;},0)/valid.length,
    b:valid.reduce(function(s,p){return s+p.b;},0)/valid.length
  };
}

function _gtCleanAutoFindSource(bg,mx,my,mw,mh){
  const W=bg.canvas.width,H=bg.canvas.height;
  const margin=Math.round(Math.max(mw,mh)*0.6);
  const step=Math.max(4,Math.round(Math.min(mw,mh)/6));
  // build offsets outward from 0 in both directions (0, +-step, +-2*step, ...)
  // instead of stepping from -margin to +margin -- when margin isn't an
  // exact multiple of step, that fixed-start loop can skip offset 0
  // entirely, which is fatal for the extremely common case of a mask
  // spanning the photo's FULL width (or height): only ox=0 (or oy=0) is
  // ever in-bounds on that axis, so missing it means zero candidates are
  // ever considered and autopatch silently fails on full-width/height
  // stamp banners.
  const offsets=[0];
  for(let d=step;d<=margin;d+=step){offsets.push(d,-d);}
  let best=null,bestScore=Infinity;
  offsets.forEach(function(oy){
    offsets.forEach(function(ox){
      const cx=mx+ox,cy=my+oy;
      if(cx<0||cy<0||cx+mw>W||cy+mh>H)return;
      const overlaps=!(cx+mw<=mx||cx>=mx+mw||cy+mh<=my||cy>=my+mh);
      if(overlaps)return;
      const score=_gtCleanBorderSSD(bg,mx,my,mw,mh,cx,cy);
      if(score<bestScore){bestScore=score;best={x:cx,y:cy,w:mw,h:mh};}
    });
  });
  return best;
}

function _gtCleanBorderSSD(bg,mx,my,mw,mh,cx,cy){
  const W=bg.canvas.width,H=bg.canvas.height;
  // Stamp banners are almost always anchored flush against one or more
  // photo edges (full-width bottom banner, corner badge, etc.), so the
  // mask commonly has ZERO margin on 2-3 of its 4 sides -- an isotropic
  // "ring all the way around" never fits in that case. Instead, treat
  // each of the 4 sides (top/bottom/left/right) independently: use
  // whichever side(s) have real margin for BOTH the mask and the
  // candidate (sized from the smaller of the two), skip sides that
  // don't, and average the SSD over whatever sides ARE usable.
  const want=Math.max(4,Math.round(Math.min(mw,mh)*0.15));
  let sum=0,n=0;
  function compareStrip(ax,ay,aw,ah,bx,by,bw,bh){
    if(aw<2||ah<2)return;
    const A=bg.getImageData(ax,ay,aw,ah).data,B=bg.getImageData(bx,by,bw,bh).data;
    const len=Math.min(A.length,B.length);
    const step=Math.max(1,Math.floor((len/4)/1000));
    for(let i=0;i<len;i+=4*step){
      const dr=A[i]-B[i],dg=A[i+1]-B[i+1],db=A[i+2]-B[i+2];
      sum+=dr*dr+dg*dg+db*db;n++;
    }
  }
  const t=Math.min(want,my,cy);
  const b=Math.min(want,H-(my+mh),H-(cy+mh));
  const l=Math.min(want,mx,cx);
  const r=Math.min(want,W-(mx+mw),W-(cx+mw));
  if(t>=2)compareStrip(mx,my-t,mw,t,cx,cy-t,mw,t);
  if(b>=2)compareStrip(mx,my+mh,mw,b,cx,cy+mh,mw,b);
  if(l>=2)compareStrip(mx-l,my,l,mh,cx-l,cy,l,mh);
  if(r>=2)compareStrip(mx+mw,my,r,mh,cx+mw,cy,r,mh);
  return n?sum/n:Infinity;
}

function _gtCleanRedo(){
  const it=_gtCleanActive();
  if(!it||!it.history||it.historyIdx>=it.history.length-1)return;
  it.historyIdx++;
  it.resultCanvas=_gtCleanCloneCanvas(it.history[it.historyIdx]);
  it.mask=null;it.src=null;
  _gtCleanRenderList();
  _gtCleanRenderBase();
}

function _gtCleanUndo(){
  const it=_gtCleanActive();
  if(!it||it.historyIdx==null||it.historyIdx<=0)return;
  it.historyIdx--;
  it.resultCanvas=_gtCleanCloneCanvas(it.history[it.historyIdx]);
  it.mask=null;it.src=null;
  _gtCleanRenderList();
  _gtCleanRenderBase();
}

function _gtCleanClear(){
  const it=_gtCleanActive();if(!it)return;
  it.mask=null;it.src=null;it.cloneSource=null;it.cloneOffset=null;
  _gtCleanRenderBase();
}

function _gtCleanAutoDetectActive(){
  const it=_gtCleanActive();
  const status=document.getElementById('gtclean-status');
  if(!it){if(typeof toast==='function')toast('⚠ Belum ada foto aktif -- upload/pilih foto dulu.');return;}
  const cv=_gtCleanEnsureWorkingCanvas(it);
  const region=_gtDetectStampRegion(cv);
  if(!region){if(status)status.textContent='⚠ Tidak menemukan area stempel otomatis di foto ini -- tandai manual (kotak merah).';return;}
  it.mask={x:region.x,y:region.y,w:region.w,h:region.h};
  it.src=null;
  _gtCleanRenderBase();
  if(status)status.textContent='Area stempel terdeteksi -- cek kotak merah di foto, geser/gambar ulang kalau meleset, lalu klik salah satu tombol proses (disarankan: Cari Otomatis + Source Patch).';
}

