function _gtCleanProcessBatch(){
  const C=window._gtClean;
  const status=document.getElementById('gtclean-status');
  if(!C.queue.length){if(typeof toast==='function')toast('⚠ Antrian foto masih kosong.');return;}
  if(status)status.textContent='Memproses batch ('+C.queue.length+' foto)...';
  setTimeout(function(){
    let ok=0,skip=0;
    C.queue.forEach(function(it){
      try{
        const cv=_gtCleanEnsureWorkingCanvas(it);
        const bg=cv.getContext('2d');
        let mask=it.mask;
        if(!mask||mask.w<4||mask.h<4){
          const region=_gtDetectStampRegion(cv);
          if(!region){skip++;return;}
          mask=region;
        }
        const found=_gtCleanAutoFindSource(bg,mask.x,mask.y,mask.w,mask.h);
        if(!found){skip++;return;}
        _gtCleanPatchFill(bg,found,mask.x,mask.y,mask.w,mask.h);
        it.mask=null;it.src=null;
        _gtCleanPushHistory(it);
        ok++;
      }catch(e){skip++;}
    });
    _gtCleanRenderList();
    _gtCleanRenderBase();
    if(status)status.textContent='✓ Batch selesai: '+ok+' foto berhasil diproses otomatis'+(skip?', '+skip+' foto dilewati (area stempel tidak terdeteksi -- tandai & proses manual satu-satu).':'.');
  },30);
}

