        const inner=walk(n);
        if(mark){const w=mark==='bold'?'b':mark==='italic'?'i':'u';out+='<'+w+'>'+inner+'</'+w+'>';}
        // DIV/P are the block wrapper Chrome inserts around each line when the
        // user presses Enter in a contenteditable -- unwrap like any other
        // unsupported tag, but append a space so "line 1" + Enter + "line 2"
        // doesn't glue into "line 1line 2" with no separator at all
        else if(tag==='DIV'||tag==='P'){out+=inner+' ';}
        else out+=inner; // unwrap any other tag (span/font/etc from paste), keep its text
      }
    });
    return out;
  }
  return walk(box);
}

function _gtRichFieldPaste(ev){
