    const hadFocus=(document.activeElement===el);
    el.innerHTML=clean;
    if(hadFocus){
      const sel=window.getSelection(),range=document.createRange();
      range.selectNodeContents(el);range.collapse(false);
      sel.removeAllRanges();sel.addRange(range);
