async function _gtCsvExifSaja(){
  var h=_gtCsvPasang();
  if(!(window._gtCsvFotos||[]).length){_gtCsvFS('Pilih foto dulu.',true);return;}
  if(!h.pairs.length){_gtCsvFS('Tidak ada foto yang cocok dengan baris data. '+_gtCsvLapor(h,0),true);return;}
  if(typeof fflate==='undefined'){_gtCsvFS('Library ZIP belum siap.',true);return;}
  var S=window._gtPts,ex=S.csvEx||{},files={},n=0;
  for(var k=0;k<h.pairs.length;k++){
    var pr=h.pairs[k],pt=_gtCsvPt(pr.row,pr.idx);
    _gtCsvFS('Menulis EXIF '+(k+1)+' / '+h.pairs.length+'...');
    await new Promise(function(r){setTimeout(r,0);});
    var f=pr.foto.file,u8=new Uint8Array(await f.arrayBuffer());
    if(!(u8[0]===0xFF&&u8[1]===0xD8)){
      var cv=document.createElement('canvas');cv.width=pr.foto.img.naturalWidth;cv.height=pr.foto.img.naturalHeight;cv.getContext('2d').drawImage(pr.foto.img,0,0);
      u8=await _gtCanvasBytes(cv,'image/jpeg',0.95);
    }else if(S.csvBersih!==false)u8=_gtCsvBuangMeta(u8);
    var alt=(pt.alt!==''&&pt.alt!=null)?pt.alt:ex.alt;
    u8=_gtInsertExif(u8,_gtCsvApp1({lat:pt.lat,lng:pt.lng,dt:pt.dt||_gtCsvSekarang(),alt:alt,desc:ex.desc,artist:ex.officer,copyright:ex.org}));
    files[_stdFileName(pr.foto.name)+'_exif.jpg']=u8;n++;
  }
  _gtCsvUnduhBlob(new Blob([fflate.zipSync(files,{level:0})],{type:'application/zip'}),'Geotag_EXIF.zip');
  _gtCsvFS('✓ '+_gtCsvLapor(h,n)+' Hasil selalu .jpg; cek lewat Properti > Rincian di Windows atau penampil EXIF online.');
}

