function _gtCsvApp1(o){
  o=o||{};
  var dt=_gtExifDT(o.dt),dtB=_gtCsvBytes(dt).slice(0,20);
  var ifd0=[],exif=[],gps=[];
  var A=function(tag,s){var b=_gtCsvBytes(s);return {tag:tag,type:2,count:b.length,bytes:b};};
  if(o.desc)ifd0.push(A(0x010E,o.desc));
  ifd0.push({tag:0x0132,type:2,count:20,bytes:dtB});
  if(o.artist)ifd0.push(A(0x013B,o.artist));
  if(o.copyright)ifd0.push(A(0x8298,o.copyright));
  ifd0.push({tag:0x8769,type:4,count:1,ptr:'exif'});
  ifd0.push({tag:0x8825,type:4,count:1,ptr:'gps'});
  exif.push({tag:0x9003,type:2,count:20,bytes:dtB});
  exif.push({tag:0x9004,type:2,count:20,bytes:dtB});
  var la=Number(o.lat),ln=Number(o.lng),hasGps=isFinite(la)&&isFinite(ln);
  gps.push({tag:0,type:1,count:4,bytes:[2,2,0,0]});
  if(hasGps){
    gps.push({tag:1,type:2,count:2,bytes:[la>=0?78:83,0]});
    gps.push({tag:2,type:5,count:3,bytes:_gtCsvRatB(_gtDMSrat(la))});
    gps.push({tag:3,type:2,count:2,bytes:[ln>=0?69:87,0]});
    gps.push({tag:4,type:5,count:3,bytes:_gtCsvRatB(_gtDMSrat(ln))});
  }
  var al=Number(o.alt);
  if(o.alt!==''&&o.alt!=null&&isFinite(al)){
    gps.push({tag:5,type:1,count:1,bytes:[al<0?1:0]});
    gps.push({tag:6,type:5,count:1,bytes:_gtCsvRatB([[Math.round(Math.abs(al)*100),100]])});
  }
  var ifds={ifd0:ifd0,exif:exif,gps:gps},order=['ifd0','exif','gps'],start={},pos=8;
  order.forEach(function(k){start[k]=pos;pos+=2+ifds[k].length*12+4;});
  var dpos=pos;
  order.forEach(function(k){ifds[k].forEach(function(e){if(e.bytes&&e.bytes.length>4){e.off=dpos;dpos+=e.bytes.length+(e.bytes.length%2);}});});
  var tiff=new Uint8Array(dpos),dv=new DataView(tiff.buffer);
  tiff[0]=0x49;tiff[1]=0x49;dv.setUint16(2,42,true);dv.setUint32(4,8,true);
  order.forEach(function(k){
    var p=start[k];dv.setUint16(p,ifds[k].length,true);p+=2;
    ifds[k].forEach(function(e){
      dv.setUint16(p,e.tag,true);dv.setUint16(p+2,e.type,true);dv.setUint32(p+4,e.count,true);
      if(e.ptr)dv.setUint32(p+8,start[e.ptr],true);
      else if(e.bytes.length>4){dv.setUint32(p+8,e.off,true);for(var i=0;i<e.bytes.length;i++)tiff[e.off+i]=e.bytes[i];}
      else for(var j=0;j<e.bytes.length;j++)tiff[p+8+j]=e.bytes[j];
      p+=12;
    });
    dv.setUint32(p,0,true);
  });
  var body=new Uint8Array(6+tiff.length);body.set([0x45,0x78,0x69,0x66,0,0],0);body.set(tiff,6);
  var len=body.length+2,seg=new Uint8Array(4+body.length);
  seg[0]=0xFF;seg[1]=0xE1;seg[2]=(len>>8)&255;seg[3]=len&255;seg.set(body,4);
  return seg;
}

function _gtCsvRatB(pairs){var a=[];pairs.forEach(function(r){a=a.concat(_gtCsvU32(r[0]),_gtCsvU32(r[1]));});return a;}

function _gtCsvU32(v){return [v&255,(v>>>8)&255,(v>>>16)&255,(v>>>24)&255];}

function _gtCsvBytes(s){var a=[],b=unescape(encodeURIComponent(String(s==null?'':s)));for(var i=0;i<b.length;i++)a.push(b.charCodeAt(i)&255);a.push(0);return a;}

function _gtCsvBuangMeta(u8){
  if(!(u8[0]===0xFF&&u8[1]===0xD8))return u8;
  var out=[0xFF,0xD8],p=2;
  while(p+3<u8.length){
    if(u8[p]!==0xFF){break;}
    var mk=u8[p+1],len=(u8[p+2]<<8)|u8[p+3];
    if(mk===0xDA){break;}
    if(mk===0xE1||mk===0xED||mk===0xFE){p+=2+len;continue;}
    for(var i=0;i<2+len;i++)out.push(u8[p+i]);
    p+=2+len;
  }
  var res=new Uint8Array(out.length+(u8.length-p));res.set(out,0);res.set(u8.subarray(p),out.length);
  return res;
}

function _gtCsvPt(r,i){
  var S=window._gtPts,la=r.lat,ln=r.lng;
  if(S.csvAcak&&(S.csvRadius==null||S.csvRadius>0)&&typeof _gtJitterCoord==='function'){var j=_gtJitterCoord(la,ln,S.csvRadius==null?8:S.csvRadius);la=j.lat;ln=j.lng;}
  return {name:r.name,lat:la,lng:ln,title:r.title,addr:r.addr,dt:r.date?(r.date+'T'+(r.time||'00:00')):'',note:r.note,deg:r.deg,alt:r.alt,temp:r.temp,wind:r.wind,_i:i};
}

function _gtCsvPasang(){
  var S=window._gtPts,fotos=(window._gtCsvFotos||[]).slice(),rows=_gtCsvRows(),pairs=[],tanpa=[],pakai={};
  var mode=S.csvMatch||'nama';
  rows.forEach(function(r,i){
    if(!_gtCsvOk(r)){tanpa.push((r.name||('baris '+(i+1)))+' (koordinat)');return;}
    var f=null;
    if(mode==='urut'){f=fotos[i]&&!pakai[i]?fotos[i]:null;if(f)pakai[i]=1;}
    else{
      var k=_gtCsvKunci(r.name);
      if(k)for(var j=0;j<fotos.length;j++){if(pakai[j])continue;var fk=_gtCsvKunci(fotos[j].name);if(fk===k||fk.indexOf(k)>=0){f=fotos[j];pakai[j]=1;break;}}
    }
    if(f)pairs.push({row:r,idx:i,foto:f});else tanpa.push(r.name||('baris '+(i+1)));
  });
  var sisa=fotos.filter(function(f,j){return !pakai[j];}).map(function(f){return f.name;});
  return {pairs:pairs,tanpaFoto:tanpa,fotoSisa:sisa};
}

function _gtCsvKunci(s){return String(s||'').toLowerCase().replace(/^.*[\\\/]/,'').replace(/\.[^.]+$/,'').replace(/[^a-z0-9]+/g,'');}

async function _gtCsvTempel(fmt){
  var h=_gtCsvPasang();
  if(!(window._gtCsvFotos||[]).length){_gtCsvFS('Pilih foto dulu.',true);return;}
  if(!h.pairs.length){_gtCsvFS('Tidak ada foto yang cocok dengan baris data. Cek pencocokan (nama file atau urutan) dan kolom nama_file. '+_gtCsvLapor(h,0),true);return;}
  if(typeof fflate==='undefined'){_gtCsvFS('Library ZIP belum siap.',true);return;}
  try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;}catch(e){}
  try{if(typeof _gmcLoadLogo==='function')await _gmcLoadLogo();}catch(e){}
  var base=_gtCsvBaseTempel(),files={},cache={},n=0;
  for(var k=0;k<h.pairs.length;k++){
    var pr=h.pairs[k],pt=_gtCsvPt(pr.row,pr.idx);
    _gtCsvFS('Menempel '+(k+1)+' / '+h.pairs.length+'...');
    await new Promise(function(r){setTimeout(r,0);});
    var st=Object.assign({},base,{lat:String(pt.lat),lng:String(pt.lng),dt:pt.dt||base.dt,remix:false});
    if(pt.title)st.title=pt.title;if(pt.addr)st.addr=pt.addr;
    _gtCsvApply(st,pt);
    if(st.showMap){var ck=pt.lat.toFixed?pt.lat.toFixed(5)+','+pt.lng.toFixed(5):st.lat+','+st.lng;if(cache[ck]===undefined)cache[ck]=await _gtFetchMapCanvas(parseFloat(st.lat),parseFloat(st.lng),st.mapStyle);st._mapCanvas=cache[ck]||null;}
    var cv=_gtCsvStampFoto({name:pr.foto.name,img:pr.foto.img,st:st});
    var nm=_stdFileName(pr.foto.name);
    if(fmt==='png')files[nm+'_geotag.png']=await _gtCanvasBytes(cv,'image/png');
    else{
      var jb=await _gtCanvasBytes(cv,'image/jpeg',1);
      try{jb=_gtInsertExif(jb,_gtCsvApp1({lat:st.lat,lng:st.lng,dt:st.dt,alt:pt.alt,desc:(window._gtPts.csvEx||{}).desc,artist:(window._gtPts.csvEx||{}).officer,copyright:(window._gtPts.csvEx||{}).org}));}catch(e){}
      files[nm+'_geotag.jpg']=jb;
    }
    n++;
  }
  _gtCsvUnduhBlob(new Blob([fflate.zipSync(files,{level:0})],{type:'application/zip'}),'Geotag_Tempel_'+(fmt==='png'?'PNG':'JPG')+'.zip');
  _gtCsvFS('✓ '+_gtCsvLapor(h,n)+(fmt==='png'?' PNG tidak membawa EXIF.':''));
}

function _gtCsvStampFoto(item){
  var G=_gtGeserDef();
  if(!G.x&&!G.y)return _gtStamp(item);
  var ov=_gtStamp(item,{overlayOnly:true}),c=document.createElement('canvas');
  c.width=ov.width;c.height=ov.height;
  var g=c.getContext('2d');g.imageSmoothingEnabled=true;g.imageSmoothingQuality='high';
  g.drawImage(item.img,0,0,c.width,c.height);
  /* posisi di preview dibaca sebagai letak relatif (0 = rapat tepi awal, 1 = rapat tepi akhir), lalu diterapkan ke ukuran stempel di foto ini */
  var S=window._gtPts,bb=S._bbox,bp=_gtGeserBBox(ov),dx=G.x,dy=G.y;
  if(bb&&bp){
    var rel=function(a,w,gg){return (1-w)<0.02?0.5:Math.max(0,Math.min(1,(a+gg)/(1-w)));};
    dx=rel(bb.x,bb.w,G.x)*(1-bp.w)-bp.x;dy=rel(bb.y,bb.h,G.y)*(1-bp.h)-bp.y;
  }
  g.drawImage(ov,Math.round(dx*ov.width),Math.round(dy*ov.height));
  return c;
}

function _gtCsvBaseTempel(){
  var S=window._gtPts,f=_gtState();
  return Object.assign({},f,{template:(typeof _gtPtsEffTemplate==='function'?_gtPtsEffTemplate():f.template),mapStyle:S.mapStyle||f.mapStyle||'street',
    brightness:S.brightness!=null?S.brightness:82,scalePct:S.scalePct!=null?S.scalePct:100,boxW:S.boxW!=null?S.boxW:f.boxW,boxH:S.boxH!=null?S.boxH:f.boxH,
    coordFmt:S.coordFmt||f.coordFmt,dateFmt:S.dateFmt||f.dateFmt,wm:S.wm||f.wm,note:S.note!=null?S.note:f.note,tz:S.tz||f.tz,
    weather:S.weather||f.weather,weatherIcon:S.weatherIcon||f.weatherIcon,report:S.report||f.report,remix:false});
}

function _gtCsvEx(k,v){var S=window._gtPts;S.csvEx=S.csvEx||{};S.csvEx[k]=String(v||'').trim();}

function _gtCsvFotoKosong(){window._gtCsvFotos=[];_gtCsvRefresh();_gtCsvStatus('Foto dikosongkan; data tabel tetap ada.');}

function _gtCsvRefresh(){
  if(window._gtCsvMap){try{window._gtCsvMap.remove();}catch(e){}window._gtCsvMap=null;}
  var el=document.getElementById('gt-pts-section');
  if(el)el.innerHTML=_gtPointsSectionInner();
  if(_gtCsvOpen('peta'))_gtCsvPetaMuat();
  if(typeof _gtPtsRefreshPreview==='function')_gtPtsRefreshPreview();
}

async function _gtCsvFotoMuat(files){
  files=Array.prototype.slice.call(files||[]);if(!files.length)return;
  var st0=document.getElementById('gt-csv-foto-status');
  var sp=await _gtCsvSiapkan(files,function(m){if(st0)st0.textContent=m;});
  var simpan=window._gtCsvFotos=window._gtCsvFotos||[],ada={},gagal=0;
  simpan.forEach(function(f){ada[f.name]=1;});
  for(var i=0;i<sp.files.length;i++){
    var f=sp.files[i];
    if(ada[f.name])continue;
    var url=URL.createObjectURL(f);
    try{
      var img=await new Promise(function(res,rej){var im=new Image();im.onload=function(){res(im);};im.onerror=rej;im.src=url;});
      simpan.push({name:f.name,file:f,img:img});ada[f.name]=1;
    }catch(e){gagal++;}finally{URL.revokeObjectURL(url);}
  }
  var info=document.getElementById('gt-csv-foto-info');if(info)info.textContent=simpan.length+' foto siap.';
  if(st0)st0.textContent=(sp.heic?sp.heic+' HEIC dikonversi ke JPG (EXIF bawaan HEIC tidak ikut terbaca). ':'')+(sp.gagalHeic?sp.gagalHeic+' HEIC gagal dikonversi. ':'')+(gagal?gagal+' foto gagal dibaca. ':'');
}

async function _gtCsvSiapkan(files,lapor){
  var out=[],heic=0,gagal=0;
  files=Array.prototype.slice.call(files||[]);
  for(var i=0;i<files.length;i++){
    var f=files[i];
    if(_gtCsvAdaHeic(f)){
      try{if(lapor)lapor('Mengonversi HEIC '+(heic+1)+'...');out.push(await _gtCsvHeicKeJpg(f));heic++;}catch(e){gagal++;}
      continue;
    }
    if(!/^image\//.test(f.type)&&!/\.(jpe?g|png|webp)$/i.test(f.name))continue;
    out.push(f);
  }
  return {files:out,heic:heic,gagalHeic:gagal};
}

async function _gtCsvHeicKeJpg(f){
  var h=await _gtCsvEnsureHeic();
  var out=await h({blob:f,toType:'image/jpeg',quality:0.92});
  var blob=Array.isArray(out)?out[0]:out;
  return new File([blob],f.name.replace(/\.(heic|heif)$/i,'.jpg'),{type:'image/jpeg',lastModified:f.lastModified||Date.now()});
}

function _gtCsvEnsureHeic(){
  return new Promise(function(res,rej){
    if(window.heic2any){res(window.heic2any);return;}
    try{
      var sc=document.createElement('script');sc.textContent=_gtCsvHeicLib();document.head.appendChild(sc);
      if(window.heic2any)res(window.heic2any);else rej(new Error('heic2any tidak termuat'));
    }catch(e){rej(e);}
  });
}

