function _gtCsvIsiInput(i,f,v){
  var inp=document.querySelector('tr.gt-csv-row[data-i="'+i+'"] input[aria-label^="'+f+' baris"]');if(inp)inp.value=v;
}

function _gtCsvJudul(r){var J=_gtCsvJ(),a=[];if(J.kota&&r.kota)a.push(r.kota);if(J.prov&&r.prov)a.push(r.prov);if(J.neg&&r.neg)a.push(r.neg);return a.length?a.join(', '):(r.kota||r.prov||r.neg||'');}

function _gtCsvJ(){var S=window._gtPts;S.csvJudul=S.csvJudul||{kota:true,prov:true,neg:true};return S.csvJudul;}

async function _gtCsvDeteksiCuaca(){
  var rows=_gtCsvRows(),ok=[];
  rows.forEach(function(r,i){if(_gtCsvOk(r)&&(r.alt===''||r.temp===''||r.wind===''))ok.push(i);});
  if(!ok.length){_gtCsvDet('Tidak ada baris yang perlu diisi (ketinggian, suhu, angin sudah ada, atau koordinat belum valid).');return;}
  var el=0,cu=0,gagal=0;
  try{
    for(var c=0;c<ok.length;c+=50){
      var ch=ok.slice(c,c+50).filter(function(i){return rows[i].alt==='';});
      if(!ch.length)continue;
      var url='https://api.open-meteo.com/v1/elevation?latitude='+ch.map(function(i){return rows[i].lat;}).join(',')+'&longitude='+ch.map(function(i){return rows[i].lng;}).join(',');
      var j=await (await fetch(url)).json();
      (j.elevation||[]).forEach(function(v,k){if(isFinite(v)){rows[ch[k]].alt=Math.round(v);el++;}});
    }
  }catch(e){gagal++;}
  for(var k=0;k<ok.length;k++){
    var r=rows[ok[k]];
    if(!(r.temp===''||r.wind===''))continue;
    if(!r.date){continue;}
    _gtCsvDet('Cuaca '+(k+1)+' / '+ok.length+'...');
    try{
      var u2='https://archive-api.open-meteo.com/v1/archive?latitude='+r.lat+'&longitude='+r.lng+'&start_date='+r.date+'&end_date='+r.date+'&hourly=temperature_2m,wind_speed_10m&timezone=auto';
      var j2=await (await fetch(u2)).json(),h=j2.hourly||{},hr=r.time?parseInt(r.time.slice(0,2),10):12;
      var t=h.temperature_2m&&h.temperature_2m[hr],w=h.wind_speed_10m&&h.wind_speed_10m[hr];
      if(r.temp===''&&t!=null&&isFinite(t)){r.temp=Math.round(t*10)/10;cu++;}
      if(r.wind===''&&w!=null&&isFinite(w))r.wind=Math.round(w*10)/10;
    }catch(e2){gagal++;}
  }
  if(typeof _gtPtsRefreshPreview==='function')_gtPtsRefreshPreview();
  _gtCsvDet('Ketinggian terisi '+el+' baris, suhu/angin '+cu+' baris'+(gagal?'; '+gagal+' permintaan gagal (offline atau tanggal belum tersedia di arsip)':'')+'.',!el&&!cu&&gagal>0);
}

function _gtCsvDet(m,galat){var el=document.getElementById('gt-csv-det-status');if(el){el.textContent=m;el.style.color=galat?'#c62828':'var(--g4)';}}

async function _gtCsvDeteksiAlamat(){
  var rows=_gtCsvRows(),n=0,gagal=0,todo=[];
  rows.forEach(function(r,i){if(_gtCsvOk(r)&&(!r.title||!r.addr))todo.push(i);});
  if(!todo.length){_gtCsvDet('Tidak ada baris yang perlu diisi (lokasi dan alamat sudah ada, atau koordinat belum valid).');return;}
  for(var k=0;k<todo.length;k++){
    var i=todo[k],r=rows[i];
    _gtCsvDet('Mencari alamat '+(k+1)+' / '+todo.length+'...');
    var ad=await _gtReverseAddr(r.lat,r.lng);
    if(ad&&(ad.title||ad.addr)){
      if(!r.title&&ad.title){var bg=String(ad.title).split(', ');r.kota=bg[0]||'';r.prov=ad.prov||(bg.length>2?bg[1]:'');r.neg=bg.length>1?bg[bg.length-1]:'';r.titleAuto=true;r.title=_gtCsvJudul(r);}
      if(!r.addr&&ad.addr)r.addr=ad.addr;_gtCsvIsiInput(i,'Lokasi',r.title);n++;}else gagal++;
    if(k<todo.length-1)await new Promise(function(res){setTimeout(res,1100);});
  }
  if(typeof _gtPtsRefreshPreview==='function')_gtPtsRefreshPreview();
  _gtCsvDet(n+' baris terisi'+(gagal?', '+gagal+' gagal (offline atau tidak ada hasil)':'')+'.',!n&&gagal>0);
}

function _gtCsvKalHtml(){
  var S=window._gtPts,rows=_gtCsvRows(),per={},bulan=S.csvKalBulan;
  rows.forEach(function(r){if(r.date){per[r.date]=(per[r.date]||0)+1;}});
  var tgl=Object.keys(per).sort();
  if(!tgl.length)return '<div style="font-size:13px;color:var(--g4)">Belum ada baris bertanggal.</div>';
  if(!bulan||!/^\d{4}-\d{2}$/.test(bulan))bulan=S.csvKalBulan=tgl[0].slice(0,7);
  var y=+bulan.slice(0,4),m=+bulan.slice(5,7),first=new Date(y,m-1,1).getDay(),dim=new Date(y,m,0).getDate();
  var nm=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'][m-1];
  var h='<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><button type="button" aria-label="Bulan sebelumnya" onclick="_gtCsvKalBulan(-1)" style="'+_gtCsvBtn()+';padding:2px 9px">‹</button><b style="font-size:13px">'+nm+' '+y+'</b><button type="button" aria-label="Bulan berikutnya" onclick="_gtCsvKalBulan(1)" style="'+_gtCsvBtn()+';padding:2px 9px">›</button>'
    +(S.csvFilter?'<button type="button" id="gt-csv-kal-semua" onclick="_gtCsvKalPilih(\'\')" style="'+_gtCsvBtn()+';margin-left:auto">Tampilkan semua</button>':'')+'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px;max-width:330px;font-size:13px;text-align:center">'
    +['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map(function(d){return '<div style="color:var(--g3)">'+d+'</div>';}).join('');
  for(var k=0;k<first;k++)h+='<div></div>';
  for(var d=1;d<=dim;d++){
    var iso=y+'-'+('0'+m).slice(-2)+'-'+('0'+d).slice(-2),n=per[iso]||0,on=S.csvFilter===iso;
    h+=n?'<button type="button" class="gt-csv-kal-hari" data-tgl="'+iso+'" aria-label="'+iso+' ('+n+' titik)" onclick="_gtCsvKalPilih(\''+iso+'\')" style="border:1px solid '+(on?'#f9a825':'var(--g2)')+';background:'+(on?'rgba(255,193,7,.35)':'rgba(106,27,154,.18)')+';color:var(--text);border-radius:6px;padding:3px 0;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit">'+d+'<span style="display:block;font-size:13px;font-weight:400">'+n+'</span></button>'
      :'<div style="padding:3px 0;color:var(--g3)">'+d+'</div>';
  }
  return h+'</div>';
}

