  if(!r.name)r.name='titik'+(_gtCsvRows().length+1);
  r.latMentah=String(r.lat);r.lngMentah=String(r.lng);
  _gtCsvRows().push(r);window._gtPts.sel=_gtCsvRows().length-1;
