function _gtCsvTerapkan(){
  var la=_gtCsvNum((document.getElementById('gt-csv-t-lat')||{}).value),ln=_gtCsvNum((document.getElementById('gt-csv-t-lng')||{}).value);
  if(!(isFinite(la)&&isFinite(ln)&&Math.abs(la)<=90&&Math.abs(ln)<=180)){_gtCsvStatus('Isi latitude dan longitude yang valid dulu.',true);return;}
  var n=0;_gtCsvRows().forEach(function(r){if(!_gtCsvOk(r)){r.lat=la;r.lng=ln;r.latMentah=String(la);r.lngMentah=String(ln);n++;}});
  _gtCsvRefresh();_gtCsvStatus('Koordinat diterapkan ke '+n+' baris. Seret pin di peta untuk menggeser per baris.');
}

