function _gtCsvUnduhData(){
  var kol=['nama_file','latitude','longitude','tanggal','jam','lokasi','alamat','catatan','arah','ketinggian','suhu','angin'];
  var q=function(v){v=String(v==null?'':v);return /[",\n;]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;};
  var out=[kol.join(',')];
  _gtCsvRows().forEach(function(r){out.push([r.name,r.lat,r.lng,r.date||r.tglMentah,r.time||r.jamMentah,r.title,r.addr,r.note,r.deg,r.alt,r.temp,r.wind].map(q).join(','));});
  _gtCsvUnduhBlob(new Blob(['﻿'+out.join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'}),'data_geotag.csv');
  _gtCsvStatus(_gtCsvRows().length+' baris diunduh sebagai data_geotag.csv (format sama dengan contoh, bisa diunggah lagi).');
}

async function _gtCsvDariFoto(files){
  files=Array.prototype.slice.call(files||[]);if(!files.length)return;
  var sp=await _gtCsvSiapkan(files,function(m){_gtCsvStatus(m);});
  files=sp.files;
  if(!files.length){_gtCsvStatus('Tidak ada foto yang bisa dibaca di pilihan itu'+(sp.gagalHeic?' ('+sp.gagalHeic+' HEIC gagal dikonversi)':'')+'.',true);return;}
  var baru=[],exif=0,sistem=0;
  for(var i=0;i<files.length;i++){
    var f=files[i],info={dt:'',lat:'',lng:'',alt:''};
    try{if(/jpe?g$/i.test(f.name)||f.type==='image/jpeg')info=_gtCsvExif(await f.arrayBuffer());}catch(e){}
    var tgl='',jam='';
    if(info.dt){var m=info.dt.match(/^(\d{4}):(\d{2}):(\d{2})\s+(\d{2}):(\d{2})/);if(m){tgl=m[1]+'-'+m[2]+'-'+m[3];jam=m[4]+':'+m[5];exif++;}}
    if(!tgl){var d=new Date(f.lastModified||Date.now());tgl=d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);jam=('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);sistem++;}
    var r=_gtCsvRow({name:f.name,lat:info.lat,lng:info.lng,date:tgl,time:jam,title:'',addr:'',note:'',deg:'',alt:info.alt,temp:'',wind:''});
    r.latMentah=info.lat===''?'':String(info.lat);r.lngMentah=info.lng===''?'':String(info.lng);
    baru.push(r);
  }
  var rs=_gtCsvRows();baru.forEach(function(r){rs.push(r);});
  window._gtPts.sel=rs.length-baru.length;
  await _gtCsvFotoMuat(files);
  _gtCsvRefresh();
  var tanpaKoor=baru.filter(function(r){return !_gtCsvOk(r);}).length;
  _gtCsvStatus(baru.length+' foto ditambahkan: tanggal/jam dari EXIF '+exif+', dari tanggal berkas '+sistem+' (perkiraan'+(sp.heic?'; '+sp.heic+' HEIC dikonversi, jamnya dari tanggal berkas':'')+').'+(tanpaKoor?' '+tanpaKoor+' foto belum punya koordinat; isi sekali lewat "Terapkan", seret pin di peta, atau lengkapi di tabel.':''));
}

function _gtCsvExif(buf){
  var out={dt:'',lat:'',lng:'',alt:'',desc:'',artist:'',copyright:''};
  try{
    var dv=new DataView(buf);if(dv.getUint16(0)!==0xFFD8)return out;
    var p=2;
    while(p+4<dv.byteLength){
      var mk=dv.getUint16(p),len=dv.getUint16(p+2);
      if(mk===0xFFE1&&dv.getUint32(p+4)===0x45786966){
        var t=p+10,le=dv.getUint16(t)===0x4949,g16=function(o){return dv.getUint16(t+o,le);},g32=function(o){return dv.getUint32(t+o,le);};
        var ifd0=g32(4),n=g16(ifd0),exifP=0,gpsP=0;
        var asc=function(e){var cnt=g32(e+4),off=cnt>4?g32(e+8):e+8,s='';for(var k=0;k<cnt-1;k++)s+=String.fromCharCode(dv.getUint8(t+off+k));return s;};
        var utf=function(e){var cnt=g32(e+4),off=cnt>4?g32(e+8):e+8,a=[];for(var k=0;k<cnt-1;k++)a.push(dv.getUint8(t+off+k));try{return decodeURIComponent(a.map(function(c){return '%'+('0'+c.toString(16)).slice(-2);}).join(''));}catch(x){return String.fromCharCode.apply(null,a);}};
        for(var i=0;i<n;i++){var e=ifd0+2+i*12,tag=g16(e);if(tag===0x8769)exifP=g32(e+8);if(tag===0x8825)gpsP=g32(e+8);if(tag===0x010E)out.desc=utf(e);if(tag===0x013B)out.artist=utf(e);if(tag===0x8298)out.copyright=utf(e);}
        if(exifP){var m=g16(exifP);for(var j=0;j<m;j++){var e2=exifP+2+j*12;if(g16(e2)===0x9003)out.dt=asc(e2);}}
        if(gpsP){
          var q=g16(gpsP),ref={},val={};
          for(var j2=0;j2<q;j2++){var e3=gpsP+2+j2*12,tg=g16(e3);
            if(tg===1||tg===3)ref[tg]=String.fromCharCode(dv.getUint8(t+e3+8));
            if(tg===5)ref[5]=dv.getUint8(t+e3+8);
            if(tg===6){var o6=g32(e3+8);val[6]=g32(o6)/Math.max(1,g32(o6+4));}
            if(tg===2||tg===4){var off=g32(e3+8),d=[];for(var k2=0;k2<3;k2++)d.push(g32(off+k2*8)/Math.max(1,g32(off+k2*8+4)));val[tg]=d[0]+d[1]/60+d[2]/3600;}}
          if(val[2]!=null)out.lat=(ref[1]==='S'?-1:1)*val[2];
          if(val[4]!=null)out.lng=(ref[3]==='W'?-1:1)*val[4];
          if(val[6]!=null)out.alt=(ref[5]===1?-1:1)*val[6];
        }
        return out;
      }
      if(mk===0xFFDA||len<2)break;
      p+=2+len;
    }
  }catch(e){}
  return out;
}

async function _gtCsvMuat(file){
  if(!file)return;
  try{
    var text=await file.text(),rows=_gtCsvParse(text);
    if(!rows.length){_gtCsvStatus('CSV kosong atau kolomnya tidak dikenali. Unduh contoh CSV untuk melihat formatnya.',true);return;}
    window._gtPts.csv=rows;window._gtPts.sel=0;window._gtPts.csvFilter='';window._gtPts.csvKalBulan='';
    var ok=rows.filter(function(r){return _gtCsvOk(r);}).length;
    _gtCsvRefresh();
    _gtCsvStatus(rows.length+' baris dimuat dari '+file.name+'. '+ok+' punya koordinat valid'+(ok<rows.length?' ('+(rows.length-ok)+' baris ditandai merah: latitude/longitude kosong atau salah)':'')+'.',ok<rows.length&&!ok);
  }catch(e){_gtCsvStatus('Gagal membaca CSV: '+String(e&&e.message||e).slice(0,100),true);}
}

function _gtCsvParse(text){
  text=String(text).replace(/^﻿/,'').replace(/\r\n?/g,'\n');
  var first=text.split('\n')[0]||'',nPk=(first.match(/;/g)||[]).length,nK=(first.match(/,/g)||[]).length,tab=(first.match(/\t/g)||[]).length;
  var d=tab>nK&&tab>nPk?'\t':(nPk>nK?';':',');
  var rows=[],row=[],cell='',q=false;
  for(var i=0;i<text.length;i++){var c=text[i];
    if(q){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else q=false;}else cell+=c;}
    else{if(c==='"')q=true;else if(c===d){row.push(cell);cell='';}else if(c==='\n'){row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}}
  if(cell!==''||row.length){row.push(cell);rows.push(row);}
  rows=rows.filter(function(r){return r.some(function(v){return String(v).trim()!=='';});});
  if(!rows.length)return [];
  var head=rows[0].map(function(h){return _gtCsvNorm(h);}),col={};
  var AL=_gtCsvAlias();Object.keys(AL).forEach(function(f){for(var i=0;i<head.length;i++){if(AL[f].indexOf(head[i])>=0){col[f]=i;break;}}});
  var out=[];
  for(var r=1;r<rows.length;r++){
    var g=function(f){return col[f]!=null?String(rows[r][col[f]]==null?'':rows[r][col[f]]).trim():'';};
    var date=g('date'),time=g('time'),dt=g('datetime');
    if(dt&&!date){var p=dt.split(/[ T]+/);date=p[0]||'';if(!time)time=p[1]||'';}
    out.push(_gtCsvRow({name:g('name'),lat:g('lat'),lng:g('lng'),date:date,time:time,title:g('title'),addr:g('addr'),note:g('note'),deg:g('deg'),alt:g('alt'),temp:g('temp'),wind:g('wind')}));
  }
  return out;
}

function _gtCsvAlias(){return {name:['namafile','filename','file','nama'],lat:['latitude','lat'],lng:['longitude','lng','long','lon'],date:['tanggal','date','tgl'],
  time:['jam','waktu','time'],datetime:['tanggaljam','datetime','waktutanggal'],title:['lokasi','judul','title','location','project','kota'],
  addr:['alamat','address'],note:['catatan','note','keterangan'],deg:['arah','arahcone','direction','azimuth'],
  alt:['ketinggian','altitude','elevasi','elevation'],temp:['suhu','temperature','temp'],wind:['angin','wind']};}

function _gtCsvNorm(h){return String(h==null?'':h).replace(/^﻿/,'').toLowerCase().replace(/[\s_\-\.]+/g,'');}

