function _ctDetectParse(raw,defZone,defHemi){
  var s=String(raw||'').replace(/\s+/g,' ').trim();if(!s)return null;
  var label='';
  var lm=s.match(/^([^,;\t0-9-][^,;\t]*?)[:\t]\s*(.+)$/);
  if(lm&&/[a-zA-Z]/.test(lm[1])){label=lm[1].trim();s=lm[2].trim();}
  // DMS
  if(/[°'\"]/.test(s)||/[NSEW]/i.test(s)&&/\d\s+\d/.test(s)){
    var parts=_ctSplitDms(s);
    if(parts){var la=_ctDmsToDec(parts[0]),ln=_ctDmsToDec(parts[1]);
      if(isFinite(la)&&isFinite(ln)&&Math.abs(la)<=90&&Math.abs(ln)<=180)return{label:label,lat:la,lng:ln};}
  }
  var nums=(s.match(/-?\d+(?:\.\d+)?/g)||[]).map(Number);
  if(nums.length>=2){
    var big=nums.filter(function(x){return Math.abs(x)>1000;});
    if(big.length>=2){
      var e=big[0],n=big[1],zone=defZone,hemi=defHemi;
      var zx=s.match(/zona?\s*(\d+)/i);if(zx&&!_utmZonaSah(parseInt(zx[1],10)))return{label:label,alasan:'Zona UTM harus 1 sampai 60 (tertulis '+zx[1]+').'};/*y724-f09*/
      var zy=s.match(/(?:^|[\s,;])(\d{1,3})\s*[NSns]\b/);if(zy&&!_utmZonaSah(parseInt(zy[1],10)))return{label:label,alasan:'Zona UTM harus 1 sampai 60 (tertulis '+zy[1]+').'};
      var zm=s.match(/zona?\s*([1-5]\d|60|[1-9])(?!\d)/i);/*Y645 F-24: dua digit dulu*/if(zm)zone=parseInt(zm[1],10);
      else{var zm2=s.match(/\b([1-5]\d|60|[1-9])\s*[A-Za-z]\b/);if(zm2)zone=parseInt(zm2[1],10);}
      var hm=s.match(/\b([NS])\b/);if(hm)hemi=hm[1].toUpperCase();
      try{var ll=_utmToLatLng(e,n,zone,hemi);if(ll&&isFinite(ll.lat))return{label:label,lat:ll.lat,lng:ll.lng};}catch(x){}
    } else {
      var a=nums[0],b=nums[1],lat,lng;
      if(Math.abs(a)<=90&&Math.abs(b)<=180){lat=a;lng=b;}
      else if(Math.abs(b)<=90&&Math.abs(a)<=180){lat=b;lng=a;}
      else{lat=a;lng=b;}
      if(isFinite(lat)&&isFinite(lng))return{label:label,lat:lat,lng:lng};
    }
  }
  return null;}

function _utmZonaSah(z){return Number.isInteger(z)&&z>=1&&z<=60;}

function _ctDmsToDec(str){var s=String(str).trim();if(!s)return NaN;
  var neg=/[SsWw]/.test(s)||/^-/.test(s);
  var n=(s.match(/\d+(?:\.\d+)?/g)||[]).map(Number);
  if(!n.length)return NaN;
  var dec=(n[0]||0)+(n[1]||0)/60+(n[2]||0)/3600;
  return neg?-dec:dec;}

function _ctSplitDms(s){
  if(/[,;]/.test(s)){var p=s.split(/[,;]/);if(p.length>=2)return[p[0],p.slice(1).join(' ')];}
  var m=s.match(/^(.*?[NSns])\s+(.*[EWew].*)$/);if(m)return[m[1],m[2]];
  return null;}

function _gtSetDms(axis,v){
  const dec=_gtDMSToDec(v);
  if(!isFinite(dec)){if(typeof toast==='function')toast('⚠ Format DMS tidak dikenali.');return;}
  _gtSet(axis==='lat'?'lat':'lng',dec.toFixed(7));
}

function _gtDMSToDec(s){
  s=String(s||'').trim();
  const m=s.match(/(-?\d+(?:\.\d+)?)[°\s]+(\d+(?:\.\d+)?)['\s]+(\d+(?:\.\d+)?)["\s]*([NSEWnsew])?/);
  if(!m)return NaN;
  const d=parseFloat(m[1]),mi=parseFloat(m[2]),se=parseFloat(m[3]),h=(m[4]||'').toUpperCase();
  let dec=Math.abs(d)+mi/60+se/3600;
  if(h==='S'||h==='W'||d<0)dec=-dec;
  return dec;
}

