function _gmcParseCsv(text){var arr=_gmcCsvRows(text);if(!arr.length)return [];
  var headers=arr[0].map(String),norm=headers.map(_gmcNormH),col={};
  Object.keys(_GMC_ALIAS).forEach(function(f){var al=_GMC_ALIAS[f].map(_gmcNormH);for(var i=0;i<norm.length;i++){if(al.indexOf(norm[i])>=0){col[f]=i;break;}}});
  var out=[];for(var r=1;r<arr.length;r++){var row=arr[r];if(!row||!row.length)continue;
    var g=function(f){return col[f]!=null?row[col[f]]:'';};var file=String(g('file')||('IMG_'+r)).trim();if(!file)continue;
    var loc=String(g('location')||''),city=String(g('city')||'')||loc;
    out.push({file:file,lat:parseFloat(g('lat')),lng:parseFloat(g('lng')),date:g('date'),time:g('time'),location:loc,address:String(g('address')||''),city:city});}
  return out;}

function _gmcCsvRows(text){
  text=String(text).replace(/^﻿/,'').replace(/\r\n?/g,'\n');
  var rows=[],row=[],cell='',q=false;
  for(var i=0;i<text.length;i++){var c=text[i];
    if(q){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else q=false;}else cell+=c;}
    else{if(c==='"')q=true;else if(c===','){row.push(cell);cell='';}else if(c==='\n'){row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}}
  if(cell!==''||row.length){row.push(cell);rows.push(row);}
  return rows.filter(function(r){return r.length&&r.some(function(v){return String(v).trim()!=='';});});
}

