async function _gmcGenerate(){var rows=window._gmcRows||[];if(!rows.length){if(typeof toast==='function')toast('⚠ Unggah CSV dulu.');return;}
  if(typeof fflate==='undefined'){if(typeof toast==='function')toast('⚠ Library ZIP belum siap.');return;}
  var s=_gmcState(),info=document.getElementById('gmc-info');var H=Math.round(s.w*0.42);var files={},mapCache={},usedPlaceholder=0;
  try{if(document.fonts&&document.fonts.ready)await document.fonts.ready;}catch(e){}
  await _gmcLoadLogo();
  var cv=document.createElement('canvas');
  for(var i=0;i<rows.length;i++){var row=rows[i];if(info)info.innerHTML='Membuat overlay '+(i+1)+' / '+rows.length+'...';await new Promise(function(r){setTimeout(r,0);});
    var mapImg=null;if(s.map!=='offline'&&isFinite(row.lat)&&isFinite(row.lng)){var ck=row.lat.toFixed(5)+','+row.lng.toFixed(5);
      if(mapCache[ck]===undefined){mapCache[ck]=await _gtFetchMapCanvas(row.lat,row.lng,s.map==='street'?'street':'satellite');}mapImg=mapCache[ck];if(!mapImg)usedPlaceholder++;}
    _gmcRenderOverlay(cv,row,{width:s.w,height:H,pos:s.pos,dateFmt:s.dateFmt,opacity:s.opacity,font:s.font,showMap:true,mapImg:mapImg,pin:s.pin,scale:s.scale,flag:s.flag!==false,badgeIcon:s.badgeIcon!==false,boxW:s.boxW,boxH:s.boxH,coordFmt:s.coordFmt,gmt:s.gmt,/*Y577*/geoEx:(typeof _gtGeoEx==='function'?_gtGeoEx(s):null)});
    var bytes=await _gtCanvasBytes(cv,'image/png');var nm=_gmcSafeName(row.file)+'.png';var base=nm,k=1;while(files[nm]){nm=_gmcSafeName(row.file)+'_'+(k++)+'.png';}files[nm]=bytes;}
  if(info)info.innerHTML='Mengcompress ZIP...';await new Promise(function(r){setTimeout(r,0);});
  var zip=fflate.zipSync(files,{level:0});var blob=new Blob([zip],{type:'application/zip'});var url=URL.createObjectURL(blob);
  var a=document.createElement('a');a.href=url;a.download='overlay_gps_'+Date.now()+'.zip';document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(url);a.remove();},1500);
  if(info)info.innerHTML='✓ '+rows.length+' overlay PNG transparan diunduh sebagai ZIP.'+(usedPlaceholder?(' ('+usedPlaceholder+' pakai peta placeholder karena tile gagal/offline)'):'');}

function _gmcSafeName(n){return String(n).replace(/[\\/:*?"<>|]/g,'_').trim()||'overlay';}

function _gmcSet(k,v){var s=_gmcState();s[k]=v;try{localStorage.setItem('env26_gmc',JSON.stringify(s));}catch(e){}
  if(typeof _gmcPreviewRow==='function')_gmcPreviewRow(window._gmcIdx||0);}

