function _etSwitchSub(sub){
  ET_SUB=sub;
  document.querySelectorAll('.et-sub-btn').forEach(b=>b.classList.remove('active'));
  const btn=document.getElementById('et-sub-'+sub);if(btn)btn.classList.add('active');
  const c=document.getElementById('et-sub-content');if(!c)return;
  if(sub==='drain')_etRenderDrain(c);
  else if(sub==='review')_etRenderReview(c);
  else if(sub==='coord')_etRenderCoordTransform(c);
  else if(sub==='rawsync'){if(typeof renderRawSync==='function')renderRawSync(c);}
  else if(sub==='dataset'){if(typeof _etRenderDataset==='function')_etRenderDataset(c);}
  else if(sub==='guide')_etRenderGuide(c);
  else if(sub==='penapisan')_etRenderPenapisan(c);
  else if(sub==='debitph')_etRenderDebitPh(c);
  else if(sub==='recon'){if(typeof _etRenderRecon==='function')_etRenderRecon(c);}
  else if(sub==='datapack')_etRenderDataPack(c);
  else if(sub==='geotag')_etRenderGeotag(c);
  else if(sub==='pdfcombine')_etRenderPdfCombine(c);
  else _etRenderCompress(c);
}

