async function _etPdfOcrReadable(file){
  if(!file||file.type!=='application/pdf'){if(typeof toast==='function')toast('⚠ Pilih file PDF terlebih dahulu.');return;}
  const resEl=document.getElementById('et-ocr-result');if(resEl){resEl.style.display='none';resEl.innerHTML='';}
  _etSetStatus('Memuat PDF...',true,'et-ocr');
  _etSetProgress(0,'et-ocr');
  try{
    await _etEnsureWorker();
    const enhance=document.getElementById('et-ocr-enhance').checked;
    const origBytes=await file.arrayBuffer();
    const pdf=await pdfjsLib.getDocument({data:origBytes,isEvalSupported:false}).promise;
    _etSetStatus('Memuat model OCR (pertama kali agak lama)...',true,'et-ocr');
    const worker=await window._ocrGetWorker();
    const {jsPDF}=window.jspdf;
    let outDoc=null;
    const nPages=pdf.numPages;
    for(let p=1;p<=nPages;p++){
      _etSetStatus(`OCR halaman ${p}/${nPages}...`,true,'et-ocr');
      _etSetProgress((p-1)/nPages*100,'et-ocr');
      const page=await pdf.getPage(p);
      const baseViewport=page.getViewport({scale:1});
      const scale=Math.min(2.5,1800/Math.max(baseViewport.width,baseViewport.height));
      const useScale=Math.max(scale,1);
      const viewport=page.getViewport({scale:useScale});
      const canvas=document.createElement('canvas');
      canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
      const ctx=canvas.getContext('2d');
      await page.render({canvasContext:ctx,viewport}).promise;
      if(enhance)_etEnhanceCanvas(ctx,canvas.width,canvas.height);
      const res=await worker.recognize(canvas);
      const imgData=canvas.toDataURL('image/jpeg',0.88);
      const wPt=baseViewport.width*0.75,hPt=baseViewport.height*0.75; // px(96dpi)->pt
      const orient=wPt>hPt?'l':'p';
      if(!outDoc)outDoc=new jsPDF({orientation:orient,unit:'pt',format:[wPt,hPt]});
      else outDoc.addPage([wPt,hPt],orient);
      outDoc.addImage(imgData,'JPEG',0,0,wPt,hPt);
      // invisible searchable/selectable text layer, positioned from the
      // OCR word boxes (canvas px -> pt: divide by useScale, then *0.75)
      const toPt=useScale>0?(0.75/useScale):0.75;
      const words=(res&&res.data&&res.data.words)||[];
      words.forEach(function(w){
        const t=(w.text||'').trim();if(!t)return;
        const bx=w.bbox||{};
        const x0=(bx.x0||0)*toPt,y1=(bx.y1||0)*toPt,y0=(bx.y0||0)*toPt;
        const hpt=Math.max(4,y1-y0);
        try{
          outDoc.setFontSize(hpt*0.82);
          outDoc.text(t,x0,y1,{renderingMode:'invisible'});
        }catch(e){}
      });
      canvas.width=0;canvas.height=0;
    }
    _etSetProgress(100,'et-ocr');
    const outBlob=outDoc.output('blob');
    const outName=file.name.replace(/\.pdf$/i,'')+'_readable.pdf';
    const url=URL.createObjectURL(outBlob);
    _etSetStatus(`✓ Selesai — ${nPages} halaman diproses.`,true,'et-ocr');
    if(resEl){
      resEl.style.display='block';
      resEl.innerHTML=`<div style="font-size:13px;color:var(--g4)">Ukuran: ${(outBlob.size/1024).toFixed(0)} KB</div><div data-y648="ocr-catatan" style="font-size:13px;color:var(--g4);margin-top:4px">Pengenalan teks memakai model ringan: judul dan teks besar biasanya terbaca, tetapi angka kecil di tabel sering keliru atau terlewat. Periksa angka penting terhadap dokumen aslinya; scan 300 dpi memberi hasil lebih baik.</div>
        <a href="${url}" download="${outName}" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh ${outName}</a>`;
    }
    _etSetProgress(null,'et-ocr');
  }catch(err){
    console.error('PDF OCR readable error',err);
    _etSetStatus('✗ Gagal memproses: '+(err&&err.message?err.message:err),true,'et-ocr');
    _etSetProgress(null,'et-ocr');
  }
}

function _etSetProgress(pct,prefix){
  const wrap=document.getElementById((prefix||'et')+'-progress-wrap'),bar=document.getElementById((prefix||'et')+'-progress-bar');
  if(!wrap||!bar)return;
  wrap.style.display=pct==null?'none':'block';
  if(pct!=null)bar.style.width=Math.max(0,Math.min(100,pct))+'%';
}

function _etSetStatus(msg,show,prefix){
  const el=document.getElementById((prefix||'et')+'-status');if(!el)return;
  el.style.display=show===false?'none':'flex';el.textContent=msg;
}

function _etEnhanceCanvas(ctx,w,h){
  const id=ctx.getImageData(0,0,w,h);
  const d=id.data;
  let lo=255,hi=0;
  for(let i=0;i<d.length;i+=4){
    const g=d[i]*0.299+d[i+1]*0.587+d[i+2]*0.114;
    if(g<lo)lo=g;if(g>hi)hi=g;
  }
  const range=Math.max(1,hi-lo);
  for(let i=0;i<d.length;i+=4){
    d[i]=Math.max(0,Math.min(255,(d[i]-lo)/range*255));
    d[i+1]=Math.max(0,Math.min(255,(d[i+1]-lo)/range*255));
    d[i+2]=Math.max(0,Math.min(255,(d[i+2]-lo)/range*255));
  }
  ctx.putImageData(id,0,0);
}

function _etEnsureWorker(){
  if(window._etWorkerP)return window._etWorkerP;
  window._etWorkerP=(async function(){
    const src=await _etPdfWorkerSrc();
    if(!_etWorkerUrl)_etWorkerUrl=URL.createObjectURL(new Blob([src],{type:'text/javascript'}));
    if(window.pdfjsLib){
      try{
        if(!_etWorkerPort){
          _etWorkerPort=new Worker(_etWorkerUrl);
          pdfjsLib.GlobalWorkerOptions.workerPort=_etWorkerPort;
        }
      }catch(e){
        /* Kalau worker sama sekali tidak bisa dibuat, pdf.js masih bisa bekerja di utas utama (lebih lambat, tetapi tidak mati tanpa penjelasan). */
        try{ pdfjsLib.GlobalWorkerOptions.workerPort=null; }catch(_e){}
        if(typeof toast==='function')toast('⚠ Pemroses PDF terpisah tidak bisa dijalankan; memakai mode lambat.');
      }
    }
    return _etWorkerUrl;
  })();
  /* gagal sekali (mis. luring dan belum tersimpan) tidak boleh mengunci selamanya: janji dibuang supaya percobaan berikutnya mengulang */
  window._etWorkerP.catch(function(){window._etWorkerP=null;});
  return window._etWorkerP;
}

async function _etPdfWorkerSrc(){
  const el=document.getElementById('pdfjs-worker-src');
  const tanda=(el&&el.textContent)||'';
  if(tanda.length>100000)return tanda;
  if(typeof window.__PDF_WORKER_SRC==='string'&&window.__PDF_WORKER_SRC.length>100000)return window.__PDF_WORKER_SRC;
  const mv=/pdf-worker-ext:([0-9a-f]+)/.exec(tanda),ver=mv?mv[1]:'';
  const ok=function(t){return typeof t==='string'&&t.length>100000&&t.indexOf('WorkerMessageHandler')>=0;};
  const idb=function(mode,val){return new Promise(function(res){try{const r=indexedDB.open('env26_pdfw',1);r.onupgradeneeded=function(){try{r.result.createObjectStore('w');}catch(e){}};r.onerror=function(){res(null);};r.onsuccess=function(){try{const st=r.result.transaction('w',mode).objectStore('w');const q=mode==='readonly'?st.get('s'):st.put(val,'s');q.onsuccess=function(){res(mode==='readonly'?(q.result||null):true);};q.onerror=function(){res(null);};}catch(e){res(null);}};}catch(e){res(null);}});};
  const simpan=await idb('readonly');
  if(simpan&&simpan.v===ver&&ok(simpan.t))return simpan.t;
  const alamat=[];try{alamat.push(new URL('pdf-worker.js',location.href).href);}catch(e){}
  const web='https://claudesharing2-creator.github.io/projectexcel/pdf-worker.js';if(alamat.indexOf(web)<0)alamat.push(web);
  let sebab='';
  for(let i=0;i<alamat.length;i++){
    try{const r=await fetch(alamat[i],{cache:'no-cache'});if(!r.ok){sebab='HTTP '+r.status;continue;}
      const t=await r.text();if(!ok(t)){sebab='isi berkas tidak lengkap';continue;}
      await idb('readwrite',{v:ver,t:t});return t;}catch(e){sebab=(e&&e.message)||String(e);}
  }
  if(simpan&&ok(simpan.t))return simpan.t;
  throw new Error('Pemroses PDF belum tersedia. Berkas "pdf-worker.js" perlu diambil sekali lewat internet (± 1,3 MB); sesudah itu tersimpan di peramban dan fitur PDF bisa dipakai luring. Sebab: '+sebab+'.');
}

async function _etPdfToText(file,format){
  format=format||'txt';
  if(!file||file.type!=='application/pdf'){if(typeof toast==='function')toast('⚠ Pilih file PDF terlebih dahulu.');return;}
  const statusEl=document.getElementById('et-p2t-status');
  const resEl=document.getElementById('et-p2t-result');if(resEl){resEl.style.display='none';resEl.innerHTML='';}
  statusEl.style.display='flex';statusEl.textContent='Memuat PDF...';
  try{
    await _etEnsureWorker();
    const bytes=await file.arrayBuffer();
    const pdf=await pdfjsLib.getDocument({data:bytes,isEvalSupported:false}).promise;
    const baseName=file.name.replace(/\.pdf$/i,'');
    let out=format==='md'?('# '+baseName+'\n\n'):'';
    for(let p=1;p<=pdf.numPages;p++){
      statusEl.textContent=`Mengekstrak teks halaman ${p}/${pdf.numPages}...`;
      const page=await pdf.getPage(p);
      const content=await page.getTextContent();
      let lastY=null,line='';const lines=[];
      content.items.forEach(it=>{
        const y=it.transform[5];
        if(lastY!==null&&Math.abs(y-lastY)>2){lines.push(line);line='';}
        line+=it.str;
        lastY=y;
      });
      if(line)lines.push(line);
      const pageText=lines.join('\n').trim();
      out+=format==='md'?(`## Halaman ${p}\n\n${pageText}\n\n`):(`===== Halaman ${p} =====\n${pageText}\n\n`);
    }
    statusEl.style.display='none';
    const blob=new Blob([out],{type:'text/plain'});
    const url=URL.createObjectURL(blob);
    const outName=baseName+(format==='md'?'.md':'.txt');
    if(resEl){
      resEl.style.display='block';
      resEl.innerHTML=`<div style="font-size:13px;padding:8px 10px;background:rgba(62,224,106,.1);border:1px solid rgba(62,224,106,.35);border-radius:8px">
        ✓ Selesai — teks diekstrak dari ${pdf.numPages} halaman.<br>
        <a href="${url}" download="${outName}" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh ${outName}</a>
      </div>`;
    }
  }catch(err){
    console.error('PDF to text error',err);
    statusEl.style.display='flex';
    statusEl.textContent='✗ Gagal mengekstrak: '+(err&&err.message?err.message:err);
  }
}

async function _etJpgToPdf(fileList){
  const files=[...fileList].filter(f=>f.type.startsWith('image/'));
  if(!files.length){if(typeof toast==='function')toast('⚠ Pilih minimal satu file gambar.');return;}
  const statusEl=document.getElementById('et-j2p-status');
  const resEl=document.getElementById('et-j2p-result');if(resEl){resEl.style.display='none';resEl.innerHTML='';}
  statusEl.style.display='flex';statusEl.textContent='Menyusun PDF...';
  try{
    const {jsPDF}=window.jspdf;
    let outDoc=null;
    for(let i=0;i<files.length;i++){
      statusEl.textContent=`Menambahkan gambar ${i+1}/${files.length}...`;
      const f=files[i];
      const dataUrl=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});
      const dims=await new Promise((res,rej)=>{const img=new Image();img.onload=()=>res({w:img.width,h:img.height});img.onerror=rej;img.src=dataUrl;});
      const wPt=dims.w*0.75,hPt=dims.h*0.75;
      const orient=wPt>hPt?'l':'p';
      const fmt=f.type.includes('png')?'PNG':'JPEG';
      if(!outDoc)outDoc=new jsPDF({orientation:orient,unit:'pt',format:[wPt,hPt]});
      else outDoc.addPage([wPt,hPt],orient);
      outDoc.addImage(dataUrl,fmt,0,0,wPt,hPt);
    }
    const outBlob=outDoc.output('blob');
    const url=URL.createObjectURL(outBlob);
    statusEl.style.display='none';
    if(resEl){
      resEl.style.display='block';
      resEl.innerHTML=`<div style="font-size:13px;padding:8px 10px;background:rgba(62,224,106,.1);border:1px solid rgba(62,224,106,.35);border-radius:8px">
        ✓ ${files.length} gambar digabung jadi satu PDF.<br>
        <a href="${url}" download="gambar-ke-pdf.pdf" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh PDF</a>
      </div>`;
    }
  }catch(err){
    console.error('JPG to PDF error',err);
    statusEl.textContent='✗ Gagal: '+(err&&err.message?err.message:err);
  }
}

async function _etPdfToJpg(file){
  if(!file||file.type!=='application/pdf'){if(typeof toast==='function')toast('⚠ Pilih file PDF terlebih dahulu.');return;}
  const statusEl=document.getElementById('et-p2j-status');
  statusEl.style.display='flex';statusEl.textContent='Memuat PDF...';
  try{
    await _etEnsureWorker();
    const bytes=await file.arrayBuffer();
    const pdf=await pdfjsLib.getDocument({data:bytes,isEvalSupported:false}).promise;
    const baseName=file.name.replace(/\.pdf$/i,'');
    for(let p=1;p<=pdf.numPages;p++){
      statusEl.textContent=`Mengekspor halaman ${p}/${pdf.numPages}...`;
      const page=await pdf.getPage(p);
      const viewport=page.getViewport({scale:2});
      const canvas=document.createElement('canvas');
      canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
      const ctx=canvas.getContext('2d');
      await page.render({canvasContext:ctx,viewport}).promise;
      const imgData=canvas.toDataURL('image/jpeg',0.9);
      const a=document.createElement('a');a.href=imgData;a.download=`${baseName}_hal${p}.jpg`;
      document.body.appendChild(a);a.click();a.remove();
      canvas.width=0;canvas.height=0;
      await new Promise(r=>setTimeout(r,200));
    }
    statusEl.textContent=`✓ ${pdf.numPages} halaman diekspor sebagai JPG.`;
  }catch(err){
    console.error('PDF to JPG error',err);
    statusEl.textContent='✗ Gagal: '+(err&&err.message?err.message:err);
  }
}

async function _etHandleFile(file,mode){
  mode=mode||'compress';
  const isUnlock=mode==='unlock';
  const prefix=isUnlock?'et-unlock':'et';
  if(!file||file.type!=='application/pdf'){if(typeof toast==='function')toast('⚠ Pilih file PDF terlebih dahulu.');return;}
  const resEl=document.getElementById(prefix+'-result');if(resEl){resEl.style.display='none';resEl.innerHTML='';}
  _etSetStatus('Memuat pdf.js...',true,prefix);
  _etSetProgress(0,prefix);
  try{
    await _etEnsureWorker();
    const quality=isUnlock?0.92:(parseFloat(document.getElementById('et-quality').value)||0.65);
    const origBytes=await file.arrayBuffer();
    const origSize=origBytes.byteLength;
    const loadingTask=pdfjsLib.getDocument({data:origBytes,isEvalSupported:false});
    const pdf=await loadingTask.promise;
    const {jsPDF}=window.jspdf;
    let outDoc=null;
    const nPages=pdf.numPages;
    for(let p=1;p<=nPages;p++){
      _etSetStatus(`Memproses halaman ${p}/${nPages}...`,true,prefix);
      _etSetProgress((p-1)/nPages*100,prefix);
      const page=await pdf.getPage(p);
      const baseViewport=page.getViewport({scale:1});
      const scale=Math.min(2,1500/Math.max(baseViewport.width,baseViewport.height));
      const viewport=page.getViewport({scale:Math.max(scale,0.75)});
      const canvas=document.createElement('canvas');
      canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
      const ctx=canvas.getContext('2d');
      await page.render({canvasContext:ctx,viewport}).promise;
      const imgData=canvas.toDataURL('image/jpeg',quality);
      const wPt=baseViewport.width*0.75,hPt=baseViewport.height*0.75; // px(96dpi)->pt
      const orient=wPt>hPt?'l':'p';
      if(!outDoc)outDoc=new jsPDF({orientation:orient,unit:'pt',format:[wPt,hPt]});
      else outDoc.addPage([wPt,hPt],orient);
      outDoc.addImage(imgData,'JPEG',0,0,wPt,hPt);
      canvas.width=0;canvas.height=0; // free memory promptly
    }
    _etSetProgress(100,prefix);
    let outBlob=outDoc.output('blob');
    let newSize=outBlob.size;
    const keptOriginal=!isUnlock&&newSize>=origSize;
    if(keptOriginal){outBlob=file;newSize=origSize;}
    const url=URL.createObjectURL(outBlob);
    const pct=origSize>0?Math.max(0,Math.round((1-newSize/origSize)*100)):0;
    const fmtKB=n=>(n/1024).toFixed(0)+' KB';
    _etSetStatus('',false,prefix);
    _etSetProgress(null,prefix);
    const outName=file.name.replace(/\.pdf$/i,'')+(isUnlock?'-unlocked.pdf':(keptOriginal?'.pdf':'-compressed.pdf'));
    if(resEl){
      resEl.style.display='block';
      resEl.innerHTML=isUnlock
        ?`<div style="font-size:13px;padding:8px 10px;background:rgba(62,224,106,.1);border:1px solid rgba(62,224,106,.35);border-radius:8px">
          ✓ Selesai — PDF disusun ulang tanpa proteksi (${fmtKB(newSize)}).<br><span data-y648="unlock-catatan" style="display:block;margin-top:4px;color:var(--g4)">Catatan: setiap halaman disusun ulang sebagai gambar, jadi teks di hasilnya tidak bisa dicari atau disalin. Bila teksnya diperlukan, jalankan alat OCR pada berkas hasil ini.</span>
          <a href="${url}" download="${outName}" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh ${outName}</a>
        </div>`
        :keptOriginal
        ?`<div style="font-size:13px;padding:8px 10px;background:rgba(255,193,7,.12);border:1px solid rgba(255,193,7,.4);border-radius:8px">
          ℹ️ PDF ini sudah efisien — hasil kompresi ternyata lebih besar dari aslinya (${fmtKB(origSize)}), jadi file asli dipertahankan agar tidak membengkak.<br>
          <a href="${url}" download="${outName}" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh ${outName}</a>
        </div>`
        :`<div style="font-size:13px;padding:8px 10px;background:rgba(62,224,106,.1);border:1px solid rgba(62,224,106,.35);border-radius:8px">
          ✓ Selesai — ${fmtKB(origSize)} → ${fmtKB(newSize)} (${pct>0?'hemat '+pct+'%':'ukuran tidak banyak berubah'})<br>
          <a href="${url}" download="${outName}" style="display:inline-block;margin-top:6px;background:#3EE06A;color:#063;font-weight:700;padding:5px 12px;border-radius:8px;text-decoration:none;font-size:13px">Unduh ${outName}</a>
        </div>`;
    }
  }catch(err){
    console.error('PDF process error',err);
    _etSetProgress(null,prefix);
    _etSetStatus('✗ Gagal memproses PDF: '+(err&&err.message?err.message:err),true,prefix);
  }
}

