      '<div class="fg" style="flex:1;min-width:200px"><label>Parameter During</label><input class="coord-in" list="et-param-list" value="'+((g.paramD||'').replace(/"/g,'&quot;'))+'" placeholder="mis. TSS + Plankton" onchange="_etSetField(\'paramD\',this.value)"></div>'+
    '</div>'+
    '<div class="fg" style="margin-bottom:10px"><label>Kewajiban / Catatan tambahan</label><textarea class="coord-in" rows="2" placeholder="mis. Wajib lapor ke pengawas HSE sebelum sampling..." onchange="_etSetField(\'oblig\',this.value)">'+(g.oblig||'')+'</textarea></div>'+
    (main?ptRowsHtml:'<div style="font-size:11px;color:var(--g3);margin-bottom:8px">Klik di peta untuk memilih titik utama, atau ketik nama well di kolom koordinat.</div>')+
    '<div style="display:flex;align-items:center;margin:8px 0 4px"><b style="font-size:13px">Titik Penaatan Tambahan (manual)</b>'+
      '<button class="coord-copy" style="margin-left:auto;border-color:#c4b5e8;color:#7c3aed" onclick="_etAddTP()">+ Tambah TP</button></div>'+
    (tpRows||'<div style="font-size:11px;color:var(--g3);padding:2px 4px">Belum ada TP tambahan.</div>')+
    (main?((typeof _printGisChecklistHtml==='function'?_printGisChecklistHtml():'')+(typeof _printMdChecklistHtml==='function'?_printMdChecklistHtml():'')+'<button class="coord-copy" style="margin-top:8px;width:100%;padding:7px;font-size:13px;font-weight:700;border-color:#1565c0;color:#1565c0" onclick="_etPrintGuide()">Cetak Panduan Sampling (peta asli, perlu internet)</button><button class="coord-copy" style="margin-top:6px;width:100%;padding:7px;font-size:13px;font-weight:700;border-color:#1565c0;color:#1565c0" onclick="_etWordGuide()">Unduh Panduan Sampling sebagai Word (.docx)</button>'):'')+
    '</div>';
  _etRenderLiveMap();
}

function _etRenderLiveMap(){
  var wrap=document.getElementById('et-guide-map-wrap');
  if(!wrap)return;
  var a=ET_GUIDE;
  var datum=a.coordDatum||'wgs84';
  var main=_coordParse(a.coordMain,datum);
  // Y420: peta TIDAK LAGI menunggu koordinat diisi. Dulu barisnya
  // `if(!main){wrap.innerHTML='';return;}` -- jadi pengguna yang membuka alat
  // ini melihat kotak kosong tanpa penjelasan, padahal petanya ada. Sekarang
  // peta selalu tampil, dan justru dipakai UNTUK memilih titiknya.
  var hasRadius=!['Drilling','CSD','Airlift','Flushing'].includes(a.type);
  var brg=(a.coordBearing!=null&&isFinite(a.coordBearing))?a.coordBearing:0;
  var upBrg=(a.coordUpBearing!=null&&isFinite(a.coordUpBearing))?a.coordUpBearing:(brg+180)%360;
  var downBrg=(a.coordDownBearing!=null&&isFinite(a.coordDownBearing))?a.coordDownBearing:brg;
  var up=(main&&hasRadius)?_coordOffset(main.lat,main.lng,500,upBrg):null;
  var down=(main&&hasRadius)?_coordOffset(main.lat,main.lng,500,downBrg):null;
  var hasFar=(a.type==='Trenching'&&a.hasFarPoint);
  var farBrg=(a.farBearing!=null&&isFinite(a.farBearing))?a.farBearing:downBrg;
  var far=(main&&hasFar)?_coordOffset(main.lat,main.lng,3500,farBrg):null;
  var tps=Array.isArray(a.coordTP)?a.coordTP:[];
  var divId='et-guide-leaflet-map';

  var hint=main
    ? (hasRadius
        ? 'Geser titik ↑/↓ merah untuk menyesuaikan (tetap terkunci di radius 500 m'+(hasFar?', titik jauh terkunci di 3500 m':'')+').'
        : 'Jenis kegiatan ini tidak punya radius kepatuhan — hanya titik utama sesuai ENV Mon Program.')
    : 'Belum ada titik utama. Klik di peta untuk memilihnya, atau ketik nama well di kolom koordinat di atas.';

  wrap.innerHTML=
    '<div class="guide-map-shell" data-y420="shell">'
      +'<div class="guide-map-side">'
        +(typeof _mapSearchHtml==='function'?_mapSearchHtml('et-guide-search'):'')
        +'<div id="et-guide-gis-note" style="margin-top:8px"></div>'
        +'<div class="guide-map-hint">'+hint+'</div>'
        +(typeof _mdPanelHtml==='function'?_mdPanelHtml():'')
      +'</div>'
      +'<div class="guide-map-main">'
        +'<div id="'+divId+'" class="guide-map-canvas"></div>'
        +(typeof _mapCoordBarHtml==='function'?_mapCoordBarHtml('et-guide-coordbar'):'')
      +'</div>'
    +'</div>';

  _coordEnsureLeaflet().then(function(){
    var el=document.getElementById(divId);
    if(!el||!document.body.contains(el))return;
    var map=L.map(el,{zoomControl:true,attributionControl:true});
    if(window._etGuideMap){try{window._etGuideMap.remove();}catch(e){}}
    window._etGuideMap=map;
    // Basemap dari modul bersama: satelit sebagai bawaan karena alat ini soal
    // titik sampling di lapangan, bukan jalan raya.
    if(typeof _mapAddBasemaps==='function')_mapAddBasemaps(map,'sat');
    else L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:18}).addTo(map);

    if(main)map.setView([main.lat,main.lng],15); else map.setView([-0.5,117.4],8);
    if(typeof _mapAttachCursorBar==='function')_mapAttachCursorBar(map,'et-guide-coordbar');
    if(typeof _mapWireSearch==='function')_mapWireSearch('et-guide-search',map);
    if(typeof _mdAttach==='function')_mdAttach(map);
    if(typeof _mapAttachGis==='function'){
      _mapAttachGis(map,function(n){
        var note=document.getElementById('et-guide-gis-note');
        if(note)note.innerHTML=n?'':((typeof _mapGisEmptyHtml==='function')?_mapGisEmptyHtml():'');
      });
    }

    // Klik peta -> tawarkan jadikan titik utama. Sengaja lewat popup, bukan
    // langsung menimpa: sekali salah klik tidak boleh menghapus titik yang
    // sudah susah payah dicari.
    map.on('click',function(ev){
      // Y422: saat alat gambar aktif, klik adalah perintah menggambar --
      // bukan tawaran mengganti titik utama. Satu klik tidak boleh berarti
      // dua hal sekaligus, apalagi kalau salah satunya menimpa data.
      if(typeof _mdActive==='function'&&_mdActive()){
        if(typeof _mdClick==='function')_mdClick(map,ev.latlng);
        return;
      }
      var la=ev.latlng.lat, ln=ev.latlng.lng;
      var txt=la.toFixed(6)+', '+ln.toFixed(6);
      var utm='';
      try{
        if(typeof _latLngToUtm==='function'){
          var u=_latLngToUtm(la,ln);
          var f=(typeof _utmThousands==='function')?_utmThousands:function(x){return x.toFixed(1);};
          utm='<div style="font-family:monospace;font-size:11px;color:#666;margin-top:2px">'
            +f(u.easting)+'E, '+f(u.northing)+'N</div>';
        }
      }catch(e){}
      L.popup({closeButton:true})
        .setLatLng(ev.latlng)
        .setContent('<div style="font-family:monospace;font-size:13px">'+txt+'</div>'+utm
          +'<button type="button" onclick="_etGuideSetMainFromMap('+la+','+ln+')" '
          +'style="margin-top:6px;width:100%;background:#1565c0;color:#fff;border:none;'
          +'border-radius:6px;padding:6px 10px;cursor:pointer;font-family:inherit;'
          +'font-size:13px;font-weight:700">Jadikan titik utama</button>')
        .openOn(map);
    });

    if(!main)return;

    var bounds=[[main.lat,main.lng]];
    var _mMain2=L.circleMarker([main.lat,main.lng],{radius:7,color:'#0f5132',weight:2,fillColor:'#27ae60',fillOpacity:1}).addTo(map);
    _addPointBubble(map,_mMain2,'Utama','pt-main');
    function addDraggable(pt,field,label,radius0){
      bounds.push([pt.lat,pt.lng]);
      var mk=L.marker([pt.lat,pt.lng],{draggable:true,icon:L.divIcon({className:'guide-drag-dot',html:'',iconSize:[14,14],iconAnchor:[7,7]})}).addTo(map);
      var bub=_addPointBubble(map,mk,label+' ('+_coordFmt(pt)+')','');
      mk.on('drag',function(){
        var cur=mk.getLatLng();
        var newBrg=_coordBearingBetween(main.lat,main.lng,cur.lat,cur.lng);
        var snap=_coordOffset(main.lat,main.lng,radius0,newBrg);
        mk.setLatLng([snap.lat,snap.lng]);
        bub.setContent(label+' ('+_coordFmt(snap)+')');
      });
      mk.on('dragend',function(){
        var cur=mk.getLatLng();
        _coordSaveGuidePoint(ET_GUIDE_ID,field,cur.lat,cur.lng);
      });
    }
    if(hasRadius){
      addDraggable(up,'up','↑ Upstream 500m',500);
      addDraggable(down,'down','↓ Downstream 500m',500);
      L.circle([main.lat,main.lng],{radius:500,color:'#7a1717',weight:2,fillColor:'#f87171',fillOpacity:.15}).addTo(map);
    }
    if(hasFar){
      addDraggable(far,'far','Titik 3500m',3500);
      L.circle([main.lat,main.lng],{radius:3500,color:'#7a1717',weight:1.5,dashArray:'6,6',fillOpacity:0}).addTo(map);
    }
    tps.forEach(function(t,i){
      var pp=(t.lat!=null&&t.lng!=null)?{lat:t.lat,lng:t.lng}:_coordParse(t.coord,datum);
      if(!pp)return;
      bounds.push([pp.lat,pp.lng]);
      var _mTp2=L.circleMarker([pp.lat,pp.lng],{radius:6,color:'#5b21b6',weight:2,fillColor:'#9333ea',fillOpacity:1}).addTo(map);
      _addPointBubble(map,_mTp2,t.label||('TP'+(i+1)),'');
    });
    try{map.fitBounds(bounds,{padding:[40,40]});}catch(e){}
  }).catch(function(){
    if(!document.body.contains(wrap))return;
    var pts=main?[{lat:main.lat,lng:main.lng,label:'Utama',color:'#27ae60'}]:[];
    if(main&&up)pts.push({lat:up.lat,lng:up.lng,label:'Up 500m',color:'#2563eb'});
    if(main&&down)pts.push({lat:down.lat,lng:down.lng,label:'Down 500m',color:'#e65100'});
    wrap.innerHTML='<div style="font-size:11px;color:var(--g3);padding:10px;text-align:center">'
      +'⚠ Peta interaktif perlu koneksi internet.'
      +(pts.length?_coordMapSvg(pts):'')+'</div>';
  });
}

function _coordMapSvg(pts){
  var real=pts.filter(function(p){return p&&isFinite(p.lat)&&isFinite(p.lng);});
  if(!real.length)return '<div style="font-size:13px;color:var(--g3);padding:22px 12px;text-align:center;background:rgba(255,255,255,.5);border-radius:12px">Isi <b>koordinat utama</b> untuk menampilkan peta.</div>';
  var lat0=real[0].lat,lng0=real[0].lng,cosl=Math.cos(lat0*Math.PI/180);
  var proj=real.map(function(p){return {x:(p.lng-lng0)*111320*cosl,y:(p.lat-lat0)*111320,p:p};});
  var xs=proj.map(function(o){return o.x;}),ys=proj.map(function(o){return o.y;});
  var minx=Math.min.apply(null,xs),maxx=Math.max.apply(null,xs),miny=Math.min.apply(null,ys),maxy=Math.max.apply(null,ys);
  var W=330,H=230,m=38;var rx=(maxx-minx)||1,ry=(maxy-miny)||1;
  var sc=Math.min((W-2*m)/rx,(H-2*m)/ry);if(!isFinite(sc)||sc<=0)sc=0.05;
  var cx0=(minx+maxx)/2,cy0=(miny+maxy)/2;
  function X(x){return (W/2+(x-cx0)*sc).toFixed(1);}
  function Y(y){return (H/2-(y-cy0)*sc).toFixed(1);}
  var byTag={};proj.forEach(function(o){byTag[o.p.tag]=o;});
  // theme-aware palette (Command dark vs Liquid Glass light)
  var _dk=(typeof _thDark==='function'&&_thDark());
  var C=_dk
    ?{bg:'#0d0f13',grid:'rgba(120,132,158,.16)',reach:'#5E6BFF',txt:'#e5e2e3',txtStroke:'#0b0c0e',north:'#ff7a6b',bar:'#9A9DA3',border:'rgba(255,255,255,.08)'}
    :{bg:'linear-gradient(160deg,#eef6ff,#eafaf1)',grid:'rgba(90,120,160,.13)',reach:'#3b82f6',txt:'#333',txtStroke:'#fff',north:'#c62828',bar:'#555',border:'rgba(0,0,0,.06)'};
  var reach='';
  if(byTag.up&&byTag.down){reach='<line x1="'+X(byTag.up.x)+'" y1="'+Y(byTag.up.y)+'" x2="'+X(byTag.down.x)+'" y2="'+Y(byTag.down.y)+'" stroke="'+C.reach+'" stroke-width="2" stroke-dasharray="5 4" opacity=".8"/>';}
  var dots=proj.map(function(o){
    var cx=X(o.x),cy=Y(o.y);
    var lbl=o.p.label||'';
    return '<g><circle cx="'+cx+'" cy="'+cy+'" r="6" fill="'+o.p.color+'" stroke="'+(_dk?'#0b0c0e':'#fff')+'" stroke-width="2"/>'+
      '<text x="'+cx+'" y="'+(parseFloat(cy)-9)+'" font-size="8.5" font-weight="700" text-anchor="middle" fill="'+C.txt+'" style="paint-order:stroke;stroke:'+C.txtStroke+';stroke-width:2.5px">'+lbl+'</text></g>';
  }).join('');
  // scale bar (approx) : draw 500 m reference
  var barPx=(500*sc).toFixed(1);var barOk=parseFloat(barPx)>10&&parseFloat(barPx)<W-2*m;
  var bar=barOk?'<g transform="translate('+m+','+(H-14)+')"><line x1="0" y1="0" x2="'+barPx+'" y2="0" stroke="'+C.bar+'" stroke-width="2"/><line x1="0" y1="-3" x2="0" y2="3" stroke="'+C.bar+'" stroke-width="2"/><line x1="'+barPx+'" y1="-3" x2="'+barPx+'" y2="3" stroke="'+C.bar+'" stroke-width="2"/><text x="'+(parseFloat(barPx)/2)+'" y="-4" font-size="8" text-anchor="middle" fill="'+C.bar+'">500 m</text></g>':'';
  return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto;background:'+C.bg+';border-radius:12px;border:1px solid '+C.border+'">'+
    '<defs><pattern id="cgrid" width="26" height="26" patternUnits="userSpaceOnUse"><path d="M26 0H0V26" fill="none" stroke="'+C.grid+'" stroke-width="1"/></pattern></defs>'+
    '<rect width="'+W+'" height="'+H+'" fill="url(#cgrid)"/>'+
    '<g transform="translate('+(W-20)+',20)"><line x1="0" y1="10" x2="0" y2="-8" stroke="'+C.north+'" stroke-width="1.6"/><path d="M-3 -4 L0 -9 L3 -4 Z" fill="'+C.north+'"/><text x="0" y="20" font-size="8" text-anchor="middle" fill="'+C.north+'" font-weight="700">N</text></g>'+
    reach+dots+bar+'</svg>';
}

function _coordFmt(p){if(!p)return '';var u=_latLngToUtm(p.lat,p.lng);return _utmThousands(u.easting)+'E, '+_utmThousands(u.northing)+'N';}

function _utmThousands(n){var p=n.toFixed(3).split('.');p[0]=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return p.join('.');}

function _latLngToUtm(lat,lng){
  var a=6378137.0,eccSquared=0.00669438,k0=0.9996;
  var LatRad=lat*Math.PI/180,LongRad=lng*Math.PI/180;
  var ZoneNumber=Math.min(60,Math.max(1,Math.floor((lng+180)/6)+1));/*y724-f09: +-180 tetap zona 1..60*/
  var LongOrigin=(ZoneNumber-1)*6-180+3;
  var LongOriginRad=LongOrigin*Math.PI/180;
  var eccPrimeSquared=eccSquared/(1-eccSquared);
  var N=a/Math.sqrt(1-eccSquared*Math.sin(LatRad)*Math.sin(LatRad));
  var T=Math.tan(LatRad)*Math.tan(LatRad);
  var C=eccPrimeSquared*Math.cos(LatRad)*Math.cos(LatRad);
  var Aa=Math.cos(LatRad)*(LongRad-LongOriginRad);
  var M=a*((1-eccSquared/4-3*eccSquared*eccSquared/64-5*eccSquared*eccSquared*eccSquared/256)*LatRad
    -(3*eccSquared/8+3*eccSquared*eccSquared/32+45*eccSquared*eccSquared*eccSquared/1024)*Math.sin(2*LatRad)
    +(15*eccSquared*eccSquared/256+45*eccSquared*eccSquared*eccSquared/1024)*Math.sin(4*LatRad)
    -(35*eccSquared*eccSquared*eccSquared/3072)*Math.sin(6*LatRad));
  var easting=k0*N*(Aa+(1-T+C)*Aa*Aa*Aa/6+(5-18*T+T*T+72*C-58*eccPrimeSquared)*Aa*Aa*Aa*Aa*Aa/120)+500000;
  var northing=k0*(M+N*Math.tan(LatRad)*(Aa*Aa/2+(5-T+9*C+4*C*C)*Aa*Aa*Aa*Aa/24
    +(61-58*T+T*T+600*C-330*eccPrimeSquared)*Aa*Aa*Aa*Aa*Aa*Aa/720));
  if(lat<0)northing+=10000000.0;
  return {easting:easting,northing:northing,zone:ZoneNumber,hemi:(lat<0?'S':'N')};
}

function _coordOffset(lat,lng,dist,brg){var R=6378137,d=dist/R,b=brg*Math.PI/180,la=lat*Math.PI/180,lo=lng*Math.PI/180;var la2=Math.asin(Math.sin(la)*Math.cos(d)+Math.cos(la)*Math.sin(d)*Math.cos(b));var lo2=lo+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(la),Math.cos(d)-Math.sin(la)*Math.sin(la2));return {lat:la2*180/Math.PI,lng:lo2*180/Math.PI};}

function _coordBearingBetween(lat1,lng1,lat2,lng2){
  var f1=lat1*Math.PI/180,f2=lat2*Math.PI/180,dl=(lng2-lng1)*Math.PI/180;
  var y=Math.sin(dl)*Math.cos(f2);
  var x=Math.cos(f1)*Math.sin(f2)-Math.sin(f1)*Math.cos(f2)*Math.cos(dl);
  return (Math.atan2(y,x)*180/Math.PI+360)%360;
}

function _etGuideSetMainFromMap(lat,lng){
  if(typeof _etSetField==='function')_etSetField('coordMain',lat.toFixed(6)+', '+lng.toFixed(6));
  if(typeof toast==='function')toast('✓ Titik utama disetel dari peta.');
}

function _etSetField(key,val){
  if(key==='coordMain'){
    var raw=val.trim();
    if((ET_GUIDE.coordDatum||'wgs84')!=='wgs84'){
      var p=_coordParse(raw,ET_GUIDE.coordDatum);
      if(p){var u=_latLngToUtm(p.lat,p.lng);raw=u.easting.toFixed(3)+', '+u.northing.toFixed(3);}
      ET_GUIDE.coordDatum='wgs84';
    }
    ET_GUIDE.coordMain=raw;
  } else if(key==='coordDatum'){
    if(val!=='wgs84'&&ET_GUIDE.coordMain){
      var p2=_coordParse(ET_GUIDE.coordMain,val);
      if(p2){var u2=_latLngToUtm(p2.lat,p2.lng);ET_GUIDE.coordMain=u2.easting.toFixed(3)+', '+u2.northing.toFixed(3);}
      ET_GUIDE.coordDatum='wgs84';
    } else { ET_GUIDE.coordDatum=val; }
  } else if(key==='coordBearing'){
    var n=parseFloat(val);ET_GUIDE.coordBearing=isFinite(n)?((n%360)+360)%360:0;
  } else {
    ET_GUIDE[key]=val;
  }
  _etSaveGuide();
  var host=document.getElementById('et-sub-content');if(host)_etRenderGuide(host);
}

function _etSaveGuide(){try{localStorage.setItem('env26_et_guide',JSON.stringify(ET_GUIDE));}catch(e){}}

function _etWordGuide(){
  var g=Object.assign({},ET_GUIDE);
  if(g.type==='Other')g.type=g.typeCustom||'Kegiatan';
  if(g.site==='Other')g.site=g.siteCustom||'';
  _coordWordGuide(ET_GUIDE_ID, g);
}

function _etPrintGuide(){
  var g=Object.assign({},ET_GUIDE);
  if(g.type==='Other')g.type=g.typeCustom||'Kegiatan';
  if(g.site==='Other')g.site=g.siteCustom||'';
  _coordPrintGuide(ET_GUIDE_ID, g);
}

function _coordPrintGuide(actId,customRec){
  var a=customRec||ACTS.find(function(x){return x.id===actId;});if(!a)return;
  var datum=a.coordDatum||'wgs84';
  var main=_coordMainUntukDokumen(a,datum);   // Y487
  if(!main){toast(a.type==='Trenching'
    ?'⚠ Trenching diukur dari titik tengah pipa — isi Titik Awal DAN Titik Akhir dulu.'
    :'⚠ Isi koordinat utama dulu.');return;}
  if(typeof navigator!=='undefined'&&navigator.onLine===false){
    toast('⚠ Tidak ada koneksi internet — pakai tombol PDF offline di bawah.');
    return;
  }
  var gisPrintData=(typeof _buildGisPrintLayers==='function')?_buildGisPrintLayers(main,3000):[];
  // Y425: gambar yang dibuat lewat alat gambar/ukur/buffer (Y422-Y424) hidup
  // di localStorage (_mdLoad), bukan di peta cetakan yang baru dibangun --
  // tanpa baris ini gambar itu tidak pernah ikut ke jendela cetak sama
  // sekali, walau sudah tersimpan dan tampil normal di peta interaktifnya.
  var mdPrintData=(window._printMdSelected!==false&&typeof _mdLoad==='function'&&typeof _mdLabel==='function')
    ?_mdLoad().map(function(sh){return {t:sh.t,pts:sh.pts,r:sh.r,style:sh.style,label:_mdLabel(sh)};})
    :[];
  var brg=(a.coordBearing!=null&&isFinite(a.coordBearing))?a.coordBearing:0;
  var upBrg=(a.coordUpBearing!=null&&isFinite(a.coordUpBearing))?a.coordUpBearing:(brg+180)%360;
  var downBrg=(a.coordDownBearing!=null&&isFinite(a.coordDownBearing))?a.coordDownBearing:brg;
  // Drilling/CSD/Airlift/Flushing have no up/down compliance radius at all —
  // just the activity's own point (per ENV Mon Program). Only applies to
  // the custom ENV Tools guide (customRec); the activity-card/ACTS path is
  // untouched, so Dredging/Leveling/Trenching's existing 500m default there
  // never changes.
  // Y492: dibaca dari a.type, jadi berlaku untuk panduan custom MAUPUN
  // kegiatan dari Daftar Kegiatan -- sebelumnya jalur kegiatan dilewatkan.
  var hasRadius=!['Drilling','CSD','Airlift','Flushing'].includes(a.type);
