function _coordPrintSection(title, main, up, down, tps, groups, sraLabel, typeLabel, areaName, mapId, extraNote){
  var beforeTxt=(groups.before.join(', ')||'-');
  var duringTxt=(groups.during.join(' + ')||'-');
  var pts=[{lat:main.lat,lng:main.lng,label:typeLabel+' Area '+areaName+'<br>('+_coordFmt(main)+')',cls:'pt-main',layer:'main'}];
  var listHtml='';
  if(up&&down){
    pts.push({lat:up.lat,lng:up.lng,labelPrefix:'Sampling point 1<br>500 m upstream<br>',label:'Sampling point 1<br>500 m upstream<br>('+_coordFmt(up)+')',cls:'pt-up',draggable:true,field:'up',liId:mapId+'-li-up',liPrefix:'500 m upstream ',radius:500,layer:'up'});
    pts.push({lat:down.lat,lng:down.lng,labelPrefix:'Sampling point 2<br>500 m downstream<br>',label:'Sampling point 2<br>500 m downstream<br>('+_coordFmt(down)+')',cls:'pt-down',draggable:true,field:'down',liId:mapId+'-li-down',liPrefix:'500 m downstream ',radius:500,layer:'down'});
    listHtml='<ol class="editable"><li id="'+mapId+'-li-up">500 m upstream ('+_coordFmt(up)+')</li><li id="'+mapId+'-li-down">500 m downstream ('+_coordFmt(down)+')</li></ol>';
  }
  (tps||[]).forEach(function(t,i){pts.push({lat:t.lat,lng:t.lng,label:(t.label||('TP'+(i+1)))+'<br>('+_coordFmt(t)+')',cls:'pt-tp',layer:'tp'});});
  return {
    html:'<div class="page-frame"><div class="guide-page">'+
      '<h1 class="editable">PEMANTAUAN LINGKUNGAN</h1>'+
      '<h2 class="editable">UNTUK KEGIATAN '+typeLabel.toUpperCase()+' '+String(areaName).toUpperCase()+'</h2>'+
      '<div class="sra editable">SRA Societal Risk Level : '+sraLabel+'</div>'+
      (listHtml?('<p class="editable">Pemantauan dilakukan di titik berikut ini untuk kegiatan :</p>'+listHtml+
        '<p class="warn editable">Mohon jika ada perubahan arah arus, untuk lokasi upstream dan downstream disesuaikan dengan kondisi aktual di lapangan.</p>'+(extraNote?'<p class="editable"><b>Kewajiban/Catatan:</b> '+_esc(extraNote)+'</p>':'')):
        (tps&&tps.length?'<p class="editable"><b>Titik tambahan:</b> '+(tps||[]).map(function(t){return _esc(t.label||'')+' → '+_coordFmt(t);}).join(', ')+'</p>':
        '<p class="editable">Pemantauan dilakukan pada titik kegiatan sesuai ENV Mon Program (lihat peta di bawah) — tidak ada radius kepatuhan upstream/downstream untuk jenis kegiatan ini.</p>'+(extraNote?'<p class="editable"><b>Kewajiban/Catatan:</b> '+_esc(extraNote)+'</p>':'')))+
      '<p class="editable">Dengan parameter <b>'+_esc(beforeTxt)+'</b> untuk kegiatan <b>before dan after '+_esc(typeLabel)+'</b>, <b>'+_esc(duringTxt)+'</b> untuk kegiatan <b>during '+_esc(typeLabel)+'</b>.</p>'+
      '<p class="editable">Berikut lokasi sampling dan koordinat (red dot point):</p>'+
      '<div class="guide-map" id="'+mapId+'"></div>'+
    '</div></div>',
    pts:pts
  };
}

function _etAddTP(){
  if(!Array.isArray(ET_GUIDE.coordTP))ET_GUIDE.coordTP=[];
  ET_GUIDE.coordTP.push({label:'TP'+(ET_GUIDE.coordTP.length+1),coord:''});
  _etSaveGuide();
  var host=document.getElementById('et-sub-content');if(host)_etRenderGuide(host);
}

function _etParamOptions(){
  try{
    var w=_bmWorking();var seen={};var out=[];
    (w.types||[]).forEach(function(t){
      (t.categories||[]).forEach(function(c){
        Object.keys(c.params||{}).forEach(function(p){
          var name=p.replace(/\s*\([^)]*\)/g,'').trim();
          if(name&&!seen[name]){seen[name]=true;out.push(name);}
        });
      });
    });
    return out.sort();
  }catch(e){return [];}
}

function _etCoordGuideInput(q){
  var box=document.getElementById('et-guide-coord-suggestions');
  if(!box)return;
  q=String(q||'').trim();
  var matches=_coordMapFilterPoints(q);
  box.innerHTML='';
  if(!matches.length){box.style.display='none';return;}
  matches.forEach(function(point){
    var b=document.createElement('button');
    b.type='button';
    b.style.cssText='display:block;width:100%;text-align:left;padding:7px 9px;border:0;border-bottom:1px solid var(--g2);cursor:pointer;font-family:inherit;background:var(--g1);color:var(--text);';
    var name=document.createElement('b');name.style.cssText='display:block;font-size:13px;line-height:1.25';name.textContent=String(point.name||'');
    var meta=document.createElement('span');meta.style.cssText='display:block;margin-top:2px;font-size:11px;color:var(--g3)';meta.textContent=String(point.src||point.cat||'')+' · '+String(point.lat_d)+', '+String(point.lng_d);
    b.appendChild(name);b.appendChild(meta);
    b.addEventListener('mousedown',function(ev){ev.preventDefault();});
    b.addEventListener('mouseenter',function(){b.style.background='var(--g2)';});
    b.addEventListener('mouseleave',function(){b.style.background='var(--g1)';});
    b.addEventListener('click',function(){_etCoordGuidePick(point);});
    box.appendChild(b);
  });
  box.style.display='block';
}

function _etCoordGuidePick(point){
  if(!point||!isFinite(Number(point.lat_d))||!isFinite(Number(point.lng_d))){
    if(typeof toast==='function')toast('⚠ Titik ini belum memiliki koordinat yang valid.');
    return;
  }
  ET_GUIDE.coordMain=String(point.lat_d)+', '+String(point.lng_d);
  ET_GUIDE.coordDatum='wgs84';
  _etSaveGuide();
  var input=document.getElementById('et-guide-coord-q');
  if(input)input.value=ET_GUIDE.coordMain;
  var box=document.getElementById('et-guide-coord-suggestions');
  if(box){box.innerHTML='';box.style.display='none';}
  if(typeof toast==='function')toast('Koordinat diisi dari "'+String(point.name||'titik terpilih')+'".');
}

function _coordMapFilterPoints(q){
  q=String(q||'').trim().toLowerCase();
  if(q.length<2)return [];
  return _coordMapPoints().filter(function(p){return p.nkey.indexOf(q)>=0;}).slice(0,20);
}

function _etRemoveTP(i){
  if(!Array.isArray(ET_GUIDE.coordTP))return;
  ET_GUIDE.coordTP.splice(i,1);
  _etSaveGuide();
  var host=document.getElementById('et-sub-content');if(host)_etRenderGuide(host);
}

function _etSetTP(i,key,val){
  if(!Array.isArray(ET_GUIDE.coordTP)||!ET_GUIDE.coordTP[i])return;
  if(key==='coord'){
    var pp=_coordParse(val,ET_GUIDE.coordDatum||'wgs84');
    ET_GUIDE.coordTP[i].coord=val;
    if(pp){ET_GUIDE.coordTP[i].lat=pp.lat;ET_GUIDE.coordTP[i].lng=pp.lng;}
  } else { ET_GUIDE.coordTP[i][key]=val; }
  _etSaveGuide();
}

function _coordCopy(txt){try{navigator.clipboard.writeText(txt);if(typeof toast==='function')toast('Koordinat disalin: '+txt);}catch(e){if(typeof toast==='function')toast(txt);}}

