}

function _ctTransform(){
  var from=document.getElementById('ct-from').value, to=document.getElementById('ct-to').value;
  if(from===to){toast('⚠ Pilih CRS asal dan tujuan yang berbeda.');return;}
  var lat,lng;
  if(from==='wgs84'){
    lat=parseFloat(document.getElementById('ct-in1').value);
    lng=parseFloat(document.getElementById('ct-in2').value);
  } else if(from==='dms'){
    lat=_dmsParse(document.getElementById('ct-in1').value);
    lng=_dmsParse(document.getElementById('ct-in2').value);
  } else if(from==='utm'){
    var e=parseFloat(document.getElementById('ct-in1').value), n=parseFloat(document.getElementById('ct-in2').value);
    var zone=parseInt(document.getElementById('ct-zone').value,10), hemi=document.getElementById('ct-hemi').value;
    if(isFinite(e)&&isFinite(n)&&zone){if(!_utmZonaSah(zone)){toast('\u26a0 Zona UTM harus 1 sampai 60 (diisi '+zone+').');return;}var ll=_utmToLatLng(e,n,zone,hemi);lat=ll.lat;lng=ll.lng;}/*y724-f09*/
  } else if(from==='p2exc'){
    var e2=parseFloat(document.getElementById('ct-in1').value), n2=parseFloat(document.getElementById('ct-in2').value);
    if(isFinite(e2)&&isFinite(n2)){
      var u=_p2excToUtm(e2,n2);
      var ll2=_utmToLatLng(u.e,u.n,UTM_DEFAULT_ZONE,UTM_DEFAULT_HEMI);lat=ll2.lat;lng=ll2.lng;
    }
  }
  if(!isFinite(lat)||!isFinite(lng)){toast('⚠ Koordinat asal tidak valid/lengkap.');return;}
  if(Math.abs(lat)>90||Math.abs(lng)>180){toast('\u26a0 Lintang harus -90 sampai 90 dan bujur -180 sampai 180.');return;}/*y724-f09*/
  if(to==='utm'||to==='p2exc'){var _al=_utmAman(lat,lng);if(_al){toast('\u26a0 '+_al);return;}}
  var outHtml='';
  if(to==='wgs84'){outHtml=_ctOutRow('Latitude',lat.toFixed(7))+_ctOutRow('Longitude',lng.toFixed(7));}
  else if(to==='dms'){outHtml=_ctOutRow('Latitude',_decToDms(lat,true))+_ctOutRow('Longitude',_decToDms(lng,false));}
  else if(to==='utm'){var uu=_latLngToUtm(lat,lng);outHtml=_ctOutRow('Zona',uu.zone+uu.hemi)+_ctOutRow('Easting',_utmThousands(uu.easting)+' m')+_ctOutRow('Northing',_utmThousands(uu.northing)+' m');}
  else{var uw=_latLngToUtm(lat,lng);var p=_utmToP2exc(uw.easting,uw.northing);outHtml=_ctOutRow('Easting',_utmThousands(p.e)+' m')+_ctOutRow('Northing',_utmThousands(p.n)+' m');}
  var out=document.getElementById('ct-out-wrap');
  out.style.display='';
  out.innerHTML='<div style="font-size:11px;color:var(--g3);margin-bottom:4px;text-transform:none;letter-spacing:.4px">Hasil</div>'+outHtml;
}

function _ctOutRow(label,val){
  return '<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;background:rgba(21,101,192,.07);border-radius:8px;margin-bottom:5px"><b style="min-width:80px;font-size:13px">'+label+'</b><span style="flex:1;font-family:monospace;font-size:13px">'+val+'</span><button class="coord-copy" data-val="'+val.replace(/"/g,'&quot;')+'" onclick="_coordCopy(this.dataset.val)">salin</button></div>';
}

function _utmToP2exc(e,n){return {e:(e-P2EXC_E_OFFSET)/P2EXC_E_SCALE, n:(n-P2EXC_N_OFFSET)/P2EXC_N_SCALE};}

function _decToDms(deg,isLat){
  var hemi=isLat?(deg>=0?'N':'S'):(deg>=0?'E':'W');
  var abs=Math.abs(deg);
  var d=Math.floor(abs);
  var mFull=(abs-d)*60;
  var m=Math.floor(mFull);
  var s=(mFull-m)*60;
  return d+'°'+m+"'"+s.toFixed(2)+'"'+hemi;
}

/*y724-f09*/function _utmAman(lat,lng){
  if(!isFinite(lat)||!isFinite(lng))return 'Koordinat belum lengkap.';
  if(lat<-80||lat>84)return 'Lintang '+lat+'\u00b0 di luar cakupan UTM (80\u00b0S sampai 84\u00b0N). Titik ini tidak punya zona UTM; pakai Decimal Degrees atau DMS.';
  if(lng<-180||lng>180)return 'Bujur '+lng+'\u00b0 di luar rentang -180\u00b0 sampai 180\u00b0.';
  return '';
}

function _dmsParse(s){
  if(!s)return null;
  var m=String(s).match(/(-?\d+(?:\.\d+)?)[°d\s]+(\d+(?:\.\d+)?)['m\s]+(\d+(?:\.\d+)?)["s]?\s*([NSEWnsew])?/);
  if(!m)return null;
  var deg=parseFloat(m[1]),min=parseFloat(m[2]),sec=parseFloat(m[3]),hemi=(m[4]||'').toUpperCase();
  var val=Math.abs(deg)+min/60+sec/3600;
  if(deg<0||hemi==='S'||hemi==='W')val=-val;
  return val;
}

